COLLDATA("tadabburur","ur",[[145,"§الأنعام\ndeeds\nقیامت کی چھوٹی اور بڑی نشانیوں کے موضوع پر کوئی کتاب پڑھئے.\nلوگوں کو نیک اعمال کا حکم دیجئے اور خود بھی انہیں بجالائیے کیونکہ یہ دونوں چیزیں لازمی طور سے ایک دوسرے کے ساتھ جڑی ہوئی ہیں.\nایک پیغام بھیجئے جس میں اپنے مسلمان بھائیوں کو ظلم سے خبردار کیجئے اور بتائیے کہ ظالم نہ دنیا میں کامیاب ہوسکتا ہے اور نہ آخرت میں.\nguid\nآپ کے نیک اعمال جتنے ہوں گے اللہ تعالیٰ کے یہاں آپ کا درجہ بھی اتنا ہی ہوگا.\nاللہ تعالیٰ کا وعدہ بدل نہیں سکتا.\nظالم نہ دنیا میں کامیاب ہوسکتا ہے اور نہ آخرت میں.\nrefl\nوَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۚ\nاعمال کے لحاظ سے لوگوں کے الگ الگ درجات ہیں۔چنانچہ ان میں جوکم برائی کرنے والے ہیں اللہ تعالیٰ انہیں زیادہ برائی کرنے والوں کے برابر نہیں کریگا،نہ پیچھے چلنے والوں کو قائد وپیشواکی طرح، اور نہ ہی سربراہ کو رعایا کی مانند درجہ دیگا۔ ہر ایک کا درجہ اس کے عمل کے مطابق ہوگا ۔جیسا کہ ثواب اور جنت پانے والوں کا معاملہ ہے کہ فائدہ میں،فلاح وکامرانی میں اور جنت کے داخلہ میں اگرچہ سارے جنتی شریک ہوں گے مگر ان کے درجات میں اتنا زیادہ فرق ہوگا جس کا علم صرف اللہ کو ہے ۔ہاں!لیکن درجات کے اس عظیم فرق اورتفاوت کے باوجودتمام اہلِ جنت اپنے آقا کی نوازشات سے خوش ہوں گے۔ (السعدی: ۲۷۴)\nاہلِ جنت، درجات ومراتب میں کم زیادہ ہیں۔ اس بات کی جانکاری کا عملی فائدہ کیا ہے؟\nوَرَبُّكَ ٱلۡغَنِيُّ ذُو ٱلرَّحۡمَةِۚ\nاللہ تعالیٰ نے اپنے بندوں کو نیک کام کرنے کا حکم دیا ہے اور برے کاموں سے منع کیا ہے ،تو یہ محض بندوں کے ساتھ رحمت وشفقت کی بناپر اور ان کی بھلائی اور مصلحت کی خاطرہے۔ ورنہ وہ اپنی ذات میں تمام مخلوقات سے بے نیاز ہے، کیونکہ نہ تو فرماں بردارلوگوں کی فرمانبرداری اس کوکچھ فائدہ پہنچاسکتی ہے، اور نہ ہی نافرمانوں کی نافرمانی اس کوکچھ نقصان پہنچا سکتی ہے ۔ (السعدی: ۲۷۴)\nمذکورہ آیت میں اللہ تعالیٰ نے مومنوں اور فاجروں کی جزاوبدلے کا ذکر کرنے کے بعد اپنی ذات کی بے نیازی کا وصف کیوں بیان کیا ہے؟\nإِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ ١٣٣\nجب تم یہ حقیقت اچھی طرح جانتے ہو کہ جس طرح دوسرے لوگ اس دنیا سے منتقل ہوگئے اسی طرح تمہارا بھی یہاں سے انتقال کرجانا یقینی ہے ۔ اور جس طرح تم سے پہلے کے لوگ دنیا سے کوچ کرگئے اور اسے تمہارے لئے خالی چھوڑگئے بالکل ایسے ہی تم بھی یہاں سے کوچ کرجاؤگے اور اپنے بعد آنے والوں کے لئے اسے چھوڑکر یہاں سے رخصت ہوجاؤگے، توپھر تم نے اسے اپنا دائمی ٹھکانہ کیوں بنارکھا ہے او ر كيوں اسے ہمیشہ رہنے والا گھر سمجھ لیا ہے؟ اور کیوں بھول گئے کہ یہ دنیا گذر گاہ ہے قیام گاہ نہیں؟ اور تمہارے سامنے وہ قیام گاہ ہے جس میں ساری نعمتیں جمع کردی گئی ہیں، اور انہیں ہر آفت اور نقصان سے محفوظ کردیا گیا ہے؟یہی تو وہ مقام اور گھر ہے جس کی طرف اوّلین وآخرین یعنی اگلے اور پچھلے لوگ بے تابانہ لپکتے رہے ہیں ۔پس یہ کتنی کم نصیبی اور بدقسمتی کی بات ہے کہ کوئی شخص کمتر وگھٹیا چیز پرمطمئن ہوبیٹھے۔ اور کس قدر ہمت کی کمی اور حوصلے کی پستی ہے کہ آدمی گھاٹے کا سودا پسند کرلے ! (السعدی: ۲۷۴)\nپچھلی قوموں اور امتوں کے ختم ہوجانے اور ان کے بعد دوسری قوموں کے ان کا جانشین بن جانے میں عقل والے کے لئے کیا سبق ہے؟\nفَقَالُواْ هَٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَٰذَا لِشُرَكَآئِنَاۖ فَمَا كَانَ لِشُرَكَآئِهِمۡ فَلَا يَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمۡۗ سَآءَ مَا يَحۡكُمُونَ ١٣٦\nشیاطین کواللہ کے شریک کا نام دیا گیا ہے ۔اس لئے کہ ان کافروں نے اللہ کی نافرمانی میں ان کی اطاعت کی تھی۔ اس طرح ان لوگوں نے اطاعت کے فرض ہونے میں شیاطین کو اللہ کے ساتھ ملادیاتھا۔ (القرطبی: ۹؍۳۹۳)\nاللہ تعالیٰ نے شیاطین کو شرکاء کا نام کیوں دیا؟\nوَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ\nعمل یعنی قتل کو شریکوں کی طرف منسوب کیا ہے حالانکہ انہوں نے بذات خود یہ کام نہیں کیا تھا ۔دراصل اس کی وجہ یہ ہے کہ ان شریکوں نے فعلِ قتل کو خوشنما بناکر ان لوگوں کو اس کے ارتکاب پر ابھارا اور آمادہ کیا ۔چنانچہ یہ ۔دعوت قتل۔خود قتل کرنے کے مترادف ہے ۔ (القرطبی: ۹؍۳۹۳)\nجو شخص برائی کو خوشنما بنائے ،اس پر ابھارے اور اس کی دعوت دے ۔کیا وہ اس برائی کے کرنے والے کی طرح مانا جائیگا؟\nوَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ ١٣٧\nمشرکین اپنی اولاد کوزمین میں زندہ دفن کردیتےتھے، اور اپنے بتوں کا تقرب پانے کے لئے بھی اپنی اولاد کوجان سے مار دیتے تھے ۔ اور یہاں آیت میں شرکاء (شریکوں) سے مراد شیاطین ہیں، یا پھر بتوں کی نگرانی کرنے والے پجاری اور مجاور مراد ہیں ۔ (لِيُرۡدُوهُمۡ) کا معنی ہے تاکہ وہ انہیں ہلاک کردیں۔یہ کلمہ ‘‘الردی ’’ سے بنا ہے جس کا معنی ہلاکت ہوتا ہے ۔ (ابن جُزی: ۱؍ ۲۸۷)\nمذکورہ آیت کے تناظرمیں اللہ تعالیٰ کا کچھ فضل وکرم بیان کیجئے جو اس نے ہم پر اپنے اس دینِ اسلام کے ذریعہ کیا ہے؟\nوَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ ١٣٧\nیہاں شرکاء یعنی شریکوں سے مراد شیاطین ہیں جو اولاد کو قتل کرنے کا حکم دیتے ہیں،اس پر اکساتے ہیں اور لوگوں کی نگاہوں میں اسے خوشنما بناتے ہیں ۔اسی طرح انسانوں میں سے وہ لوگ بھی مراد ہیں جو اس گھناؤنے عمل پر لوگوں کو ابھارتے رہے ہیں اور اس عمل کو ایک زمانے سے دوسرے زمانے میں منتقل کرتے رہے ہیں ۔کیونکہ یہ سب کے سب اس عمل کی برائی میں شریک ہیں، اور آخرت میں اس کے نتائج میں بھی برابر کے حصے دار ہیں۔ (ابن عطیہ: ۲؍ ۳۴۹)\nآدمی شیطان کا شریک کار کب بن جاتا ہے؟\nwords\nمَكَانَتِكُمتمہارا طریقہ.\nعَاقِبَةُ الدَّارِاچھا انجام ۔ بہترین نتیجہ.\nذَرَأَپیدا کیا.\nالحَرثِزراعت.\nلِيُردُوهُمتاکہ انہیں ہلاک کرے.\nوَلِيَلبِسُواتاکہ وہ اسے خلط ملط کردیں.\nيَفتَرُونَوہ جھوٹ گھڑتے ہیں."],[146,"§الأنعام\ndeeds\nاللہ تعالیٰ سے دعا مانگتے رہئے کہ آپ کی اولاد کو نیک بنائے، اور آپ کوان کی بہترین تربیت کرنے کی توفیق دے.\nایسا وقت تلاش کیجئے جس میں فقراء کی حاجت شدید ہوجاتی ہو پھر ایسے وقت صدقہ دیجئے ہوسکتا ہے کہ اس سے آپ کے اجر میں اضافہ ہو.\nکچھ بھی کھائیے اور پیجئے تو اللہ کی حمد کیجئے.\nguid\nاولیاء اور مزارات کے نام پر نذر ماننا ،مشرکین کے کاموں میں سے ہے ۔اور اسے شیطان نے جاہل مسلمانوں کی نظر میں اچھا اور خوبصورت عمل بنادیا ہے.\nفیملی پلاننگ جاہلیت کے اعمال میں سے ہے، اور یہ اللہ تعالیٰ کے ساتھ بدگمانی کی قبیل سے ہے.\nفضول خرچی بری عادت ہے ،اللہ سبحانہ وتعالیٰ اسے ناپسند کرتاہے، چنانچہ آپ فضول خرچی کرنے والوں میں سے نہ بنئے.\nrefl\nوَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ١٣٩\n(إِنَّهُۥ حَكِيمٌ عَلِيمٞ) یقیناًاللہ تعالیٰ پوری پوری حکمت والا،ہر چیز کا علم رکھنے والا ہے۔ یہ جملہ پچھلے جملے میں مذکورسزا کی دھمکی کی وجہ بیان کررہا ہے کیونکہ جو ذات حکمت والی،علم والی ہے وہ ان مشرکین سے سرزد ہونے والی حرکت کا بدلہ اور مزہ نہ چکھائے، یہ بات ناممکن اور مشکل ہے ۔کیونکہ ان کے جرم کی سزادینا حکمت کے تقاضوں میں سے ہے ۔ (الالوسی: ۸؍۳۸۹)\nمذکورہ آیت کو اللہ عزوجل کی دوصفات ‘‘حکمت اور علم’’ کا ذکر کرکے ختم کیا گیا ہے ۔اس کا کیا فائدہ ہے؟\nوَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ١٣٩\nآیت میں اس بات کی دلیل ہے کہ عالم کو اپنے مخالف کی بات جاننا اور معلوم کرنا چاہئے۔گرچہ اسے قبول نہ کرے،تاکہ مخالف کے قول کی خرابی سے واقف ہوجائے اور یہ جان لے کہ اس کی تردید کیسے کی جائے ۔ اس لئے کہ اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم اور آپ کے اصحاب کرام رضی اللہ عنہم کو اس زمانے کے مخالفین کے قول وخیال کی جانکاری دی تاکہ وہ ان کے قول وفکر کی خرابی پہچان لیں۔ (القرطبی: ۹؍۴۸)\nوہ عظیم الشان فائدہ بتائیے جو طالبِ علم اس آیت سے سیکھتا ہے ؟\nوَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ١٣٩\nمشرکین کی احمقانہ رائے کا ایک نمونہ یہ تھا کہ انہوں نے بعض مویشیوں کوطے کررکھا تھا اور یہ متعین کرلیا تھا کہ ان کے پیٹ میں جو بچہ ہے اس کا کھانا عورتوں کے لئے حرام ہے اورمردوں کے لئے حلال چنانچہ ان کا کہنا تھا: (مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا) ان چوپایوں کے پیٹ میں جو بچہ ہے وہ صرف ہمارے مردوں کے لئے حلال ہے، اس میں عورتیں شریک اور حصہ دار نہیں ہیں۔ (وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ ) اور ہماری عورتوں پر اس کا کھانا حرام ہے ۔ یہ اس وقت ہوتا جب پیٹ کا بچہ زندہ پیدا ہو۔اگر بچہ مردہ پیدا ہوتا تو پھر اس کے کھانے میں وہ سب شریک اور حصہ دار ہوتے، یعنی وہ مردوں اور عورتوں دونوں کے لئے حلال ہوتا۔ (السعدی: ۲۷۶)\nآیت میں انسانوں کے بنائے ہوئے قوانین اور شریعت اسلامیہ کے درمیان موازنہ کیا گیا ہے۔ اس کی وضاحت کیجئے.\nقَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ سَفَهَۢا بِغَيۡرِ عِلۡمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّواْ وَمَا كَانُواْ مُهۡتَدِينَ ١٤٠\nجو لوگ اللہ کی خوشنودی اور ثواب کی چاہت میں عمل اور محنت کرتے ہیں لیکن اس کے بجائے اللہ کے غضب اور سزا کے شکار ہوجاتے ہیں ،ایسے لوگوں کے عمل کے لئے قرآن میں خُسران یعنی خسارے اور گھاٹے کا استعارہ (یعنی حرفِ تشبیہ کے بغیر لفظ کے مجازی معنی مرادلینا) کثرت سے آیا ہے ۔اس کی وجہ یہ ہے کہ انہوں نے خود کو مشقت میں تو مبتلا کیا لیکن نتیجہ اس کے برعکس حاصل ہوا جس کے لئے خود کو تھکایا اور ہلکان کیا تھا۔ (ابن عاشور: ۸؍۱۱۳)\nحقیقی نقصان کیا ہے جس کا ذکر قرآن میں آیا ہے؟\nوَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ\nاللہ تعالیٰ نے لوگوں کو حکم دیا ہے کہ پھلوں اور غلوں کی فصل کو جس دن کاٹا جائے اسی دن ان کا حقِ زکاۃ ادا کردیں کیونکہ یہی وقت ہوتا ہے جب فقیر ومحتاج لوگوں کے دلوں میں اس کے ملنے کی امید بندھ جاتی ہے ۔نیزاسی وقت کھیتی کی زکاۃ نکال دینا کھیتی والوں کے لئے آسان ہوتا ہے ۔اور جو اسی وقت زکاۃ نکال دے اس کے لئے معاملہ صاف اور ظاہر بھی ہوتا ہے، یہاں تک کہ زکاۃ نکالنے والا ،نہ نکالنے والے سے الگ ہوجاتا ہے ۔ (السعدی: ۲۷۶)\nکھیتی اور فصل کی زکاۃ ان کی کٹائی کے دن ہی نکال دینے کا حکم کیوں دیا گیا ہے؟\nوَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ ١٤١\nامام زُہری رحمہ اللہ کہتے ہیں:اس کا مطلب ہے کہ اللہ تعالیٰ کی معصیت ونافرمانی میں خرچ مت کرو۔ ایسا ہی قول مجاہد رحمہ اللہ سے بھی مروی ہے ۔ چنانچہ ابن ابی حاتم رحمہ اللہ نے اُن سے روایت نقل کی ہے کہ وہ کہتے ہیں:اگر ابو قُبیس پہاڑ سونے کا ہوجائے اور کوئی آدمی اسے پورا کا پورا اللہ تعالیٰ کی فرمانبرداری میں خرچ کردے تو وہ فضول خرچ نہیں ہوگا۔اس کے برخلاف اگر وہ اللہ تعالیٰ کی نافرمانی میں ایک روپیہ بھی خرچ کرے تو وہ اسراف اورفضول خرچی کرنے والا ہوجائیگا۔ (الألوسی: ۸؍۳۹۲)\nعلماءِ سلف کی تفسیر کے مطابق آیت بالا میں منع کردہ فضول خرچی کیا ہے؟\nوَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ ١٤١\nیعنی: کھانے میں حد سے تجاوزنہ کرواس لئے کہ اس میں عقل اور بدن دونوں کا نقصان ہے۔جیسا کہ اللہ تعالیٰ کا فرمان ہے: (وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ) (سورۂ اعراف: ۳۱) اور کھاؤ اور پیو مگر حد سے نہ گذرجاؤ، بلاشبہ اللہ تعالیٰ حد سے نکل جانے والوں کو پسند نہیں فرماتا۔ صحیح بخاری میں تعلیقاً یہ حدیث مروی ہے: ‘‘وَکُلُوْا وَاشْرَبُوْا وَاَلْبِسُوْا وَتَصَدَّقُوْا مِنْ غَیْرِ اِسْرَافٍ وَلَا مَخِیْلَۃٍ ’’۔یعنی کھاؤ،پیو،پہنو اور صدقہ کرو بشرطیکہ ان میں اسراف اور تکبر نہ ہو۔ (ابن کثیر: ۲؍۱۷۴)\nہمیں کھانے میں اسراف یعنی حد سے نکل جانے سے کیوں منع کیا گیا ہے؟\nwords\nحِجرٌحرام.\nمَعرُوشَاتٍچھت کے لیے محتاج /جیسے انگور؛ اور وہ ڈالیں جنہیں اس درخت کو سہارا دینے کے لیے نصب کیا جاتا ہے۔ تاکہ وہ زمین سے اونچا ہو.\nوَغَيرَ مَعرُوشَاتٍوہ درخت جو اپنے تنے پر کھڑا ہو جیسے کھجور.\nحَمُولَةًجو سواری کے لیے تیار ہو جیسے اونٹ.\nوَفَرشًاوہ جوسواری کے لیے تیار نہ ہو ؛ اپنی کم عمری کی وجہ سے ؛ زمین سے قربت کی وجہ سے۔ جیسے بکری."],[147,"§الأنعام\ndeeds\nآیت میں مذکور حرام اشیاء کی اقسام اکٹھی کیجئے اور انہیں اچھی طرح جان لیجئے.\nایک مضمون لکھ کر لوگوں کو بتائیے کہ حرام کے مقابلے میں حلال غذائیں زیادہ بھی ہیں اور بابرکت بھی ۔چنانچہ ہمیں انہی کو اپنے لئے کافی سمجھنا چاہئے.\nآپ جو غذائیں کھاتے ہیں ان پر غور کیجئے، اور ان میں سے جو حرام ہیں یا جن میں شبہ ہے انہیں چھوڑدیجئے ،اس لئے کہ حرام کا نتیجہ دین ،عقل اور بدن سب کے لئے برا ہوتا ہے.\nguid\nاس سے بڑا ظالم کوئی نہیں ہوسکتا جواللہ کی طرف منسوب کرکے جھوٹی بات کہے اور اس کے بندوں کے لئے ایسی چیز کو شریعت کا حصہ بتائے جسے اللہ نے مشروع نہ کیا ہو.\nوہ مفتی جو لوگوں کو حلال اور حرام کے فتوے دیتا ہو اس پر واجب ہے کہ اس کے فتاویٰ علم پر مبنی ہوں، ورنہ وہ بھی اس وعید میں داخل ہوجائیگا.\nمجرموں کو اللہ تعالیٰ کی طرف سے ڈھیل دیا جانا اس بات کی دلیل نہیں ہے کہ وہ ان کی گرفت نہیں کریگا،اس لئے کہ کوئی نہیں جانتا کہ اللہ کی پکڑکب آجائے؟\nrefl\nأَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٤٤\n(أَمۡ كُنتُمۡ شُهَدَآءَ)کیا تم حاضر تھے! یعنی کیا تم اللہ کے پاس موجود تھے جب اس نے اسے حرام قراردیا؟ اب جب ان پر یہ بات لازم ٹھہری کہ وہ اپنے دعوے کی دلیل اور حجت پیش کریں تو وہ اللہ پر جھوٹ باندھنے لگے او ر کہنے لگے کہ :اللہ نے ایسا حکم دیا ہے، اللہ نے ایسا ہی حکم دیا ہے۔چنانچہ اللہ تعالیٰ نے فرمایا: (فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ) پھر بتلاؤ! اس آدمی سے زیادہ ظلم کرنے والا کون ہوگا جو لوگوں کو گمراہ کرنے کے لئے کسی دلیل اور علم کے بغیر اللہ پر جھوٹ بات باندھے ۔ اس طرح اللہ نے صاف صاف بیان کردیا کہ وہ اپنے دعوے اور بات میں جھوٹے ہیں کیونکہ انہوں نے ایسی بات کہی ہے جس پر کوئی دلیل نہیں ہے ۔ (القرطبی: ۹؍۷۹)\nہر وہ شخص جو کسی حکم شرعی یا مسئلے یا نئے پیش آنے والے معاملے میں بات کرنا چاہے ،اس کے لئے کیا واجب ہے؟\nفَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٤٤\nاللہ تعالیٰ نے ان کے جھوٹ باندھنے کے برے مقصد کو بیان کیا ہے، کیونکہ اگر کوئی شخص اللہ تعالیٰ پر بے مقصد بھی جھوٹ باندھے تو یہ عظیم ظلم ہوگا۔تو پھر ایسا جھوٹ باندھنا کتنا سنگین ظلم ہوگاجس کا مقصد ایک پوری امت کو گمراہ کرنا ہو! (ابن عطیہ: ۲؍ ۳۵۵)\nجھوٹ کے برے سے برے درجات ہیں۔ ان میں سے کون سا جھوٹ سب سے نچلے درجے کا ہے؟\nفَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٤٤\nظلم کی ایک شکل یہ ہے کہ کوئی شخص دین میں ۔علم کے بغیر۔فتویٰ دینے کی جرأت کرے۔ جب تک اسے اس بات کا غالب گمان نہ ہو کہ وہ درست فتویٰ دے سکتا ہے جس پر اللہ راضی ہوگا۔او ر یہ اس وقت ہوگا جب وہ مجتہد ہو۔تب ایسی دلیل کی بنیاد پر فتویٰ دے جس کے متعلق اس کا گمان غالب ہو کہ یہ اللہ کی مراد کے مطابق ہے۔اوراگر وہ مقلد ہے تو اپنے اس غالب گمان کی بنیاد پر فتویٰ دے کہ اس کا فتویٰ اس کے امام کے مذہب کے مطابق ہے جس کی اس نے تقلید کی ہے۔ (ابن عاشور:۸؍۱۳۵) نوٹ: یہاں قول امام یا مذہبِ امام کی بنیاد پر فتویٰ دینے کا جو ذکر ہے وہ جواز کے لئے ہے یا بیانِ واقعہ کے لئے ہے مکمل واضح نہیں ہے اس کے باوجود یہ عرض کردینا ضروری ہے کہ بہت سے اہل علم نے یہ صراحت فرمائی ہے کہ جو شخص قرآن یا حدیث کی دلیل جانے بغیر محض اقوال رجال کی بنیاد پر فتویٰ دیتا ہے تو وہ بغیر علم کے فتویٰ دیتا ہے، اس لئے کہ علم قرآن وحدیث اور اجماع کا نام ہے، لہذا وہ بغیر علم کے فتویٰ دینے والوں میں شامل ہوگا۔ (دیکھئے اعلام الموقّعین لابن القیم وغیرہ فی مبحث التقلید۔ مترجم)\nعلم کے بغیر فتویٰ دینے کی جرأت کرنا جائز نہیں ہے۔اس کی وضاحت کیجئے.\nأَوۡ دَمٗا مَّسۡفُوحًا\nیہ وہ خون ہے جو ذبح کرنے کے وقت ذبح کئے جانے والے جانورکے گلے سے بہتا ہے ۔اس لئے کہ اس خون کا بدن میں رکا رہنا نقصاندہ ہے لہذا جب یہ خون جانور کے بدن سے بہہ نکلے تو اس کا گوشت کھانے میں ضرر اور نقصان نہیں رہ جاتا۔ (السعدی: ۲۷۷)\nاللہ تعالیٰ نے جانور کو ذبح کرتے وقت اس کا خون بہانے کا حکم کیوں دیا ہے؟\nأَوۡ دَمٗا مَّسۡفُوحًا\n(بہنے والا خون حرام ہے۔) اس لفظ کا مفہوم یعنی مخالف مطلب یہ ہوا کہ جانور کو ذبح کرنے کے بعد جو خون گوشت اور رگوں میں باقی رہ جاتا ہے ،بہہ کر نکلتا نہیں وہ حلال اور پاک ہے۔ (السعدی: ۲۷۷)\nاللہ تعالیٰ نے ہمارے لئے بہنے والے خون کا حکم بیان کردیاکہ وہ حرام ہے۔تو ذبح کے بعد جانور کے جسم واعضاء اور رگوں میں باقی رہ جانے والے خون کا کیا حکم ہے؟\nوَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ ١٤٦\nیعنی: آیت میں ذکر کردہ چیزوں کو حرام قرار دیا جانا ان کی سزا کے طور پر تھا (بِبَغْيِهِمْ) یعنی ان کی سرکشی پر۔ اور ان کی سرکشی تھی :انبیاء کرام علیہم السلام کو قتل کرنا،لوگوں کواللہ کے راستے سے روکنا،سود لینا،باطل طریقوں سے لوگوں کا مال ہڑپ کرنا اور اسے جائز سمجھناوغیرہ۔ (البغوی: ۲؍ ۷۵)\nگناہ،گناہ گار کے حق میں بدبختی اور برائی کا سبب ہوتا ہے۔آیت کے تناظرمیں اس بات کی وضاحت کیجئے.\nوَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ ١٤٦\n(وَعَلَى ٱلَّذِينَ هَادُواْ ) یعنی بطور خاص یہودیوں پر حرام کیا۔ (بِبَغۡيِهِمۡۖ) یعنی ان کے ظلم کے بدلے میں۔ اور وہ ظلم تھا: ان کا انبیاء کرام علیہم السلام کو ناحق قتل کرنااورسود کھاناجبکہ انہیں اس سے منع کیا گیا تھا ۔اسی طرح لوگوں کے اموال باطل وناجائز طریقوں سے کھانا بھی ان کا ظلم تھا،اور یہ یہود جب جب کسی معصیت ونافرمانی کا ارتکاب کرتے تو ان کے لئے حلال کی گئی چیزوں میں سے کسی چیز کو ان پر حرام کرکے انہیں سزا دی جاتی رہی۔ (الألوسی: ۸؍۴۰۵)\nنیک اور صالح لوگوں کو ستانا اور انہیں جان سے ماردینا،ربانی سزاؤں اور قدرتی آفتوں کا پیغام اوراعلان ہے۔اس بات کی وضاحت کیجئے.\nwords\nأَزوَاجٍأصناف / جوڑے.\nأُهِلَّ لِغَيرِ اللَّهِجس پر بوقت ذبح غیر اللہ کا نام لیا جائے.\nكُلَّ ذِي ظُفُرٍوہ جس کی انگلیوں میں فاصلہ نہ ہو جیسے اونٹ اور چوپائے.\nالحَوَايَاانتڑیاں."],[148,"§الأنعام\ndeeds\nمنافقوں کے ذرائع ابلاغ کی تعیین کرکے ان کا بائیکاٹ کیجئے، کیونکہ وہ انہی کے واسطے سے اپنے جھوٹ اور فریب کی اشاعت وترویج کرتے ہیں.\nآج کوئی ایسا بڑانیک کام کیجئے جسے آپ کے والدین کے حق میں حسن سلوک کے طور پرشمار کیا جائے۔ چاہے وہ زندہ ہوں یا نہ ہوں، کیونکہ اللہ تعالیٰ نے آپ کو ان کے ساتھ بہترین سلوک کرنے کا حکم دیا ہے.\nاس آیت میں اللہ تعالیٰ نے جن باتوں کا حکم دیا اور تلقین کی ہے ان کو اچھی طرح سمجھ لیجئے تاکہ اس کے احکام کی بھلے طور سے تعمیل کرسکیں.\nguid\nاگر آپ کسی ظالم کو سرکشی میں آگے بڑھتا ہوا دیکھیں تو غم نہ کریں ۔بیشک اللہ تعالیٰ مجرموں پر عذاب ضرور نازل کرتا ہے اور جب اس کا عذاب آجاتا ہے تو کوئی اسے روک نہیں سکتا.\nداعی اس بات کے لئے ہمیشہ تیار رہے کہ اس کا کوئی مدعو اسے جھٹلاسکتا ہے تاکہ جب بھی اس کی تکذیب کی جائے تو یہ عمل اسے دعوت سے روکنے کا سبب نہ بننے پائے.\nہدایت تو اللہ سبحانہ وتعالیٰ کے ہاتھ میں ہی ہے چنانچہ آپ اسی سے مانگئے.\nrefl\nفَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةٖ وَٰسِعَةٖ\nیہ ارشاد رسول اللہ صلی اللہ علیہ وسلم کو جھٹلانے والوں کو شوق اور رغبت دلارہا ہے کہ وہ بھی اللہ کی کشادہ اورلامحدودرحمت کی چاہت و طلب میں لگ جائیں، اور رسول صلی اللہ علیہ وسلم کی اتباع کریں۔ (ابن کثیر: ۲؍۱۷۷)\nآیت میں لوگوں کے رسول اللہ صلی اللہ علیہ وسلم کو جھٹلانے کا ذکر کرنے کے بعد اللہ کی رحمت کا تذکرہ کیوں کیا گیا؟\nسَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءٖۚ\nمشرکین نے اللہ کے امر ونہی ،اس کی پسند اور ناپسند نیز فرمانبرداری اور نافرمانی کی نفی اور انکارکرنے کے لئے تقدیرکودلیل بنایا ہے ۔اگر کوئی شخص ایسا کرتا ہے تو کھلاہوا کفر کرتا ہے۔ (ابن تیمیہ: ۳؍ ۱۱۲)\nآیت کریمہ کی روشنی میں بیان کیجئے کہ امر ونہی یعنی شریعت کے انکار پر تقدیر سے دلیل پکڑنا کتنا خطرناک ہے؟\nقُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ\nان آیتوں میں جن حرام کردہ چیزوں کا بیان ہے ،ان کی حرمت پر تمام پچھلی شریعتیں متفق ہیں ۔کسی بھی شریعت میں کبھی ان کا حکم منسوخ نہیں ہوا۔ابن عباس رضی اللہ عنہما کہتے ہیں : یہی وہ کلمات یعنی وہ احکامات ہیں جنہیں اللہ تعالیٰ نے موسیٰ علیہ السلام پر نازل فرمایا تھا ۔ (ابن جُزی: ۱؍ ۲۹۱)\nآیت میں بیان کردہ وصیتوں کو کون سا امتیاز اور خصوصیت حاصل ہے؟\nقُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ\nاس آیت میں اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کو حکم دیا ہے کہ وہ دنیا کے تمام لوگوں کو دعوت دے کر اور بلا کر انہیں اللہ کی حرام کردہ چیزیں پڑھ کر سنائیں۔ اور بالکل اسی طرح آپ صلی اللہ علیہ وسلم کے بعد امت کے علماء کا فرض ہے کہ وہ لوگوں تک اللہ کے احکام پہنچائیں اور لوگوں کے سامنے صاف صاف بیان کردیں کہ اللہ نے کن چیزوں کو ان پر حرام کیا ہے اور کون سی چیزیں حلال رکھی ہیں۔ (القرطبی: ۹؍۱۰۶)\nاس آیت میں اللہ تعالیٰ نے ہمیں کس چیز کی طرف دعوت دی ہے اور کس بات پر ابھارا ہے؟\nوَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ إِمۡلَٰقٖ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ\nسورۂ اِسراء (بنی اسرائیل:۳۱) میں فرمایا: (وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٍ) اور مفلسی کے ڈر سے اپنی اولاد کو ہلاک نہ کرو۔ یعنی: انہیں اس خوف سے مارنہ ڈالو کہ ان کی وجہ سے آئندہ فقر ومحتاجی آجائیگی ۔اسی لئے وہاں یہ فرمایا: (نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡ) ہم ہی انہیں روزی دیتے ہیں اور تمہیں بھی۔ تو پہلے ان بچوں کو روزی دینے کا ذِکر کیا ،ان کے معاملے کو اہمیت دینے کے لئے کہ ان کے رزق اور کھانے پینے کی وجہ سے تم اپنی مفلسی وفقیری کے خوف میں مبتلا نہ ہوجاؤ کیونکہ اس کا ذمہ اللہ تعالیٰ پر ہے۔ مگر یہاں یعنی مذکورہ آیت میں چونکہ پہلے سے مفلسی کی حالت (مِنْ إِمۡلَٰقٍ) (مفلسی کی وجہ سے )موجود ہے اسی لئے فرمایا: (نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡ) ہم ہی ہیں جو تمہیں بھی روزی دیتے ہیں اور ان کو بھی دیتے ہیں۔ کیونکہ یہاں ان کے اپنے رزق کا ذکرپہلے کرنااہم ہے۔ (ابن کثیر: ۲؍ ۱۸۰)\nاس سورت(اَنعام)کی مذکورہ آیت میں ماں باپ کے رزق کو اولاد کے رزق سے پہلے اور سورۂ اسراء میں اولاد کی روزی کو ماں باپ کی روزی سے پہلے کیوں ذکر کیا گیا ہے؟\nوَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ\nیعنی: بے حیائی کی باتیں اور گناہ کھلے ہوں یا چھپے ہوں، ان کے قریب بھی نہ پھٹکو،یا جن بے حیائیوں کا تعلق ظاہر سے ہے اور جن کا تعلق دل اور باطن سے ہے، دونوں کے قریب مت جاؤ ۔ اور بے حیائی کی باتوں کے قریب جانے سے بھی منع کردینا صرف ان کے ارتکاب سے ممانعت کے مقابلے میں زیادہ معنی خیزاورمؤثر ہے ، اس لئے کہ قریب جانے کی ممانعت ، ان گناہوں کے مقدمات اور ان تک پہنچانے والے وسائل وذرائع کی ممانعت کو بھی شامل ہے ۔ (السعدی: ۲۸۰)\nفحش کاموں کے قریب جانے سے کیوں منع کیا گیا ہے، اور صرف بے حیائی کے ارتکاب سے ممانعت پر اکتفا کیوں نہیں کیا گیا؟\nوَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ\n(کسی جان کو ناحق مارنا) دراصل اللہ تبارک وتعالیٰ نے تاکید کی خاطر اس کی ممانعت کو خاص طور سے بیان فرمایا ہے۔ورنہ اس سے پہلے کے حکم میں یہ بھی داخل ہے۔ چنانچہ صحیحین میں حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے ،وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے:“کوئی بھی مسلمان آدمی جو گواہی دیتا ہو کہ اللہ کے سوا کوئی معبود برحق نہیں ہے اور میں اللہ کا رسول ہوں،اس کا خون حلال نہیں ہے سوائے اس کے کہ تین میں سے کوئی ایک حالت ہو: شادی شدہ زانی ہو،یاجان کے بدلے جان لی جائے، یا جماعت سے الگ ہو کر اپنے دین سے پھر جانے والا مرتد ہو۔” (ابن کثیر: ۲؍ ۱۸۰)\nبڑے گناہوں سے ممانعت کے حکم میں قتل نفس بھی داخل ہے ۔پھر اس سے منع کرنے کے حکم کو کیوں دہرایا گیا ہے؟\nwords\nبَأسُهُاس کا عذاب.\nتَخرُصُونَتم جھوٹ بولتے ہو.\nهَلُمَّلے آؤ.\nيَعدِلُونَوہ اس کے برابر کرتے ہیں ؛ شریک ٹھہراتے ہیں.\nإِملاَقٍفقر."],[149,"§الأنعام\ndeeds\nبراہ راست کسی یتیم کی کفالت کیجئے یا اس معاملے میں کسی بھروسہ مند ادارے کا تعاون کیجئے ۔بیشک اللہ تعالیٰ نے یتیم کے مال کی اچھی دیکھ ریکھ کا حکم دیا ہے تو سوچئے خود یتیم کی راست پرورش کرنا کتنی اہمیت والا ہوگا.\nناپ تول میں کمی کرنے والے کسی تاجر کو نصیحت کیجئے.\nاپنے آپ کو ہمیشہ انصاف کی بات کہنے کا عادی بنائیے، چاہے کبھی اپنی ذات کے خلاف ہی کوئی بات کیوں نہ کہنی پڑجائے.\nguid\nاسلام پر جمے رہنا اور راہ حق سے بھٹکی ہوئی ملتوں اوربدعتی مسالک سے دوری اختیار کرنا ہی وہ صراط مستقیم ہے جو جنت تک پہنچاتا ہے.\nیقیناًاللہ تعالیٰ نے یتیموں کے حقوق پامال کرنے اورناجائز طریقوں سےان کا مال کھانے سے ڈرایا ہے چنانچہ آپ ان باتوں سے بہت دور رہئے.\nجس کا بھی کام یا تجارت ناپ تول سے جڑی ہوئی ہو ،وہ اللہ سے ڈرے اور ڈنڈی مارنے سے بچتا رہے.\nrefl\nوَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ\nیعنی: ایسا طریقہ اختیار کرو جس سے یتیم کے مال میں بہتری اور زیادتی ہو ۔یہ چیز اس کے اصل سرمائے اور پونجی کی حفاظت اور اس کے منافع اور فائدے کو بڑھانے کے ذریعہ ہوسکتی ہے ۔ (القرطبی: ۹؍۱۱۱)\nیتیم کے مال کی بہتری اور اصلاح کیسے ہوسکتی ہے؟\nوَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ\nیہاں مال کی حفاظت میں یتیم کے حق کوخاص طور پر ذکر کرنے کی وجہ یہ ہے کہ: سرپرست اور ذمہ دار کی جانب سے اس کے حق میں ظلم وزیادتی کا امکان ہوتا ہے اور اس کی وجہ یہ ہوتی ہے کہ عام طور سے یتیم کی حمایت کرنے والا اور اس کی طرف سے دفاع کرنے والا موجود نہیں ہوتا۔ (ابن عاشور: ۸؍۱۶۴)\nآیت کریمہ میں یتیم کے مال کی حفاظت کا حق خصوصیت سے ذکر کرنے کی کیا وجہ ہے؟\nوَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ\nیعنی: ہم آدمی کو اتنا ہی مکلف اور پابند بناتے ہیں جتنی اس کی طاقت ہو ،اس چیز کا مکلف نہیں بناتے جو اسے تنگی اور دشواری میں ڈال دے یا جو اس کے بس سے باہر ہو ۔اب جو کوئی ناپ تول کو مکمل کرنے کی پوری کوشش کرے‘پھر بھی اس سے کوئی کمی ہوجائے جس میں اس کی اپنی کوتاہی اور جان بوجھ کر غلطی نہ ہوئی ہو تو اللہ معاف کرنے والا ،بہت بخشنے والا ہے۔ (السعدی: ۲۸۰)\nناپ تول کو پورا کرنے کا حکم دینے کے بعد یہ ذکر کیوں کیا گیا کہ کسی شخص کو اس کی طاقت وسکت سے زیادہ کا مکلف نہیں بنایا جاتا؟\nوَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ ١٥٣\n(ٱلسُّبُلَ) (غلط راستے) کا معنی عام ہے ۔اس میں یہودیت ،نصرانیت ،مجوسیت اسلام کے علاوہ دیگرتمام دین وملت والے ،اسی طرح اہل بدعات وضلالت جو خواہشات کی پیروی کرنے والے اور فروعی احکام ومسائل میں شذوذ اور اہلِ حق سے علیحدگی ومخالفت اختیار کرنے والے اور ان کے علاوہ بحث وجدال میں باریک بینی اور بال کی کھال اتارنے والے نیز علم کلام میں غور وخوض کرنے والے اور اس میں عقلی گھوڑے دوڑانے والے سب شامل ہیں۔ یہ سب کے سب راستے۔ ادیان ومذاہب اور مسالک۔ غلطیوں اور ٹھوکروں کی زد میں ہیں اور عقیدے کی خرابی کے خطرے میں ہیں۔ (القرطبی: ۹؍۱۱۷)\nوہ راستے کیا ہیں جن کی اتباع کرنے سے اللہ نے ہمیں ڈرایا ہے؟\nوَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ ١٥٣\n(وَلَا تَتَّبِعُواْ ٱلسُّبُلَ) اور دوسری راہوں پر نہ چلو۔ یعنی: الگ الگ دین کے راستے جیسے یہودیت ،نصرانیت اور ان کے علاوہ دوسرے باطل ادیان ومذاہب۔ اس میں بدعتیں اور گمراہ کن خواہشات بھی داخل ہیں ۔اور حدیث میں ہے کہ “نبی صلی اللہ علیہ وسلم نے ایک لکیر بنائی پھر فرمایا: “هٰذَا سَبِیْلُ اللہ”یہ اللہ کا راستہ ہے۔ پھر اس لکیر کے دائیں اور بائیں جانب کچھ لکیریں کھینچیں،اس کے بعد فرمایا: “هٰذِهٖ كُلُّهَا سُبُلٌ عَلٰی کُلِّ سَبِیْلٍ مِنْہَا شَیْطَانٌ یَدْعُواِلَیْہِ”یہ سب الگ الگ راستے ہیں،ان میں سے ہر راستے پر ایک شیطان ہے جو اسی کی طرف بلاتا ہے۔ (ابن جُزی: ۱؍ ۲۹۲)\nاہل سنت کے منہج کے مخالف بعض فرقوں کی طرف نسبت کرنا اور اس کی یہ دلیل دینا کہ اس فرقے میں کچھ خیر وبھلائی بھی ہے۔یہ آپ کی رائے میں کیسا ہے؟\nوَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ\nاللہ نے اپنے راستے کو واحدکے لفظ سے ذکر کیا ہے اس لئے کہ حق ایک ہی ہے ،جبکہ اس کے برخلاف دوسری راہوں کو (السُّبُلَ) جمع کے لفظ سے تعبیر کیا ہے کیونکہ ان کے بہت سے فرقے اور گروہ ہیں ۔جدا جد ا،الگ الگ راستے ہیں۔ (ابن کثیر: ۲؍ ۱۸۲)\nاللہ کا راستہ مفرد اور غیر اللہ کے راستوں کے لئے جمع کا صیغہ کیوں آیا ہے؟\nوَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ\nاس قرآن سے بہت سی برکتیں اور بھلائیاں حاصل کی جاتی ہیں ،کوئی خیر وبھلائی ایسی نہیں ہے جس کی طرف اس کتاب نے دعوت نہ دی ہو اور اس کی ترغیب نہ دی ہو۔ اور ہر بھلائی کی حکمتیں اور مصلحتیں بھی بیان کی ہیں جو لوگوں کو بھلائیاں کرنے پر ابھارتی ہیں ۔اسی طرح کوئی بھی شر اور برائی ہو اس کتاب نے اس سے ضرور روکا ہے ،ڈرایا ہے ،اس پر عمل کرنے سے نفرت دلانے والے اسباب اور اس کے تباہ کن انجام کو بھی بیان کردیا ہے۔ (السعدی: ۲۸۱)\nیہ کتاب(یعنی قرآن کریم) برکتوں کی حامل اور بھلائیوں پر مشتمل ہے ۔ان برکتوں کی کیا شکلیں ہیں؟\nwords\nيَبلُغَ أَشُدَّهُوہ سن بلوغت کو پہنچ جائے ۔ اسے عقل آجائے.\nبِالقِسطِعدل کے ساتھ.\nدِرَاسَتِهِماپنی کتابوں کا مطالعہ.\nوَصَدَفَاور اس نے منہ موڑا."],[150,"§الأنعام\ndeeds\nاس آیت سے دلیل دیتے ہوئے کسی قبر پرست کو نصیحت کیجئے کہ اللہ کے علاوہ کی عبادت نہیں کی جاسکتی.\nاپنے تمام اعمال میں اللہ تعالیٰ سے اخلاص کی توفیق مانگئے ۔ اور کوئی بھی نیک عمل کریں تو اخلاصِ نیت کا خاص خیال رکھ کر کریں.\nکسی محتاج کے ساتھ بھلائی کیجئے.\nguid\nتوبہ اور نیک اعمال میں ٹال مٹول نہ کیجئے۔ ہوسکتا ہے کہ آپ پر وہ وقت آجائے جب آپ کے لئے یہ ممکن ہی نہ رہ جائیں.\nمشرکین کی مخالفت کیجئے اور صرف اللہ تعالیٰ کے لئے ہی ذبح کیجئے.\nداعی کو اپنی دعوت میں الگ الگ طریقے استعمال کرنے چاہئے۔کبھی لوگوں کو اللہ کے عذاب اور سزا سے ڈرانے کا اسلوب اپنائے ، کبھی انہیں اللہ کی نعمتوں اور رضامندی کا شوق دلائے اور بسااوقات یہ دونوں پہلو بیک وقت اختیار کرے.\nrefl\nيَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ قُلِ ٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ ١٥٨\nعلماء کرام کہتے ہیں:کسی بھی شخص کے لئے ایمان لانااس وقت بے فائدہ ہوگا جب سورج مغرب سے طلوع ہوجائیگا، کیونکہ یہ چیز لوگوں کے دلوں میں ایسا خوف اور ایسی دہشت بٹھادیگی جس سے ان کے نفس کی ہر خواہش مٹ جائیگی اور تن بدن کی ہر قوت کمزور بلکہ بے زور ہوجائیگی۔اس وقت چونکہ تمام لوگوں کو یقین ہوجائیگا کہ قیامت بالکل قریب آچکی ہے اس لئے سب کے سب ایسی حالت میں ہوں گے جیسی قریب المرگ شخص کی حالت ہوتی ہے جسے یقین ہوجاتا ہے کہ اس کا دنیا سے رخصتی کا وقت آچکا ہے۔اس حالت میں اس کے اندر کسی بھی قسم کے گناہ کا کوئی جذبہ اور کسی بھی معصیت ونافرمانی کی کوئی چاہت نہیں رہ جاتی ۔یعنی جرم کی خواہش اور کشش ان سے کٹ جاتی ہے اور ان کے جسموں کی گناہ کرنے کی صلاحیت وتوانائی بیکار ہوجاتی ہے ۔لہذا جو کوئی اس طرح کی حالت میں توبہ کریگا تو اس کی توبہ قبول نہیں ہوگی ،اسی طرح جیسے موت کے آجانے اور اس کی علامتوں کے ظاہرہوجانے کے وقت آدمی کی توبہ قبول نہیں ہوتی۔ (القرطبی: ۹؍۱۳۰)\nجب سورج مغرب سے طلوع ہوجائیگا تو اس کے بعد ایمان لانا کیوں فائدہ مند نہیں ہوگا؟\nيَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ\nاس بات کی حکمت ظاہر ہے۔وہ یہ ہے کہ ایمان تو وہی فائدہ دیتا ہے جو بالغیب یعنی بن دیکھے لایا جائے ،اور بندہ اپنے ارادے اور اختیار سے ایمان لایا ہو، مگر جب اللہ کی نشانیاں ،موت کی علامتیں سامنے آجائیں تو اب معاملہ غیب کا نہیں رہ جاتا بلکہ مشاہدے کا ہوجاتا ہے ۔ اس لئے اب ایمان لانے میں کوئی فائدہ نہیں رہ جاتا کیونکہ یہ تو بدیہی اورمجبوری کی حالت میں ایمان لانے کی مانند ہوجاتا ہے ۔جیسے کوئی آدمی پانی میں ڈوب رہا ہو یا آگ میں جل رہا ہو یا اس طرح کی کسی اور حالت میں ہو تو ایسا شخص موت کو اپنے سامنے دیکھ کر اپنے اندر سے انکار اور کفر کو نکال پھینکتا ہے اور ایمان لانے کا دم بھرتا ہے ۔(السعدی: ۲۸۱)\nآیت کے تناظر میں اختصار کے ساتھ ایمان بالغیب کی اہمیت بتائیے.\nأَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ\nانسان اپنے ایمان کی بدولت ہی خیر وبھلائی حاصل کرتا ہے ،چنانچہ فرمانبرداری،نیکی اور تقویٰ کا فائدہ اور ان میں ترقی اور اضافہ اسی وقت ہوگا جب بندے کے دامن میں ایمان کی دولت ہو ۔ایمان ہوگا تبھی یہ بھلائیاں نشونماپائیں گی اور پھل اور سایہ دیں گی،لیکن جب دل ایمان کے جوہر سے خالی ہو تو ان میں سے کوئی بھی چیز بندے کے لئے فائدہ مند نہیں ہوتی۔ (السعدی: ۲۸۲)\nکفار ومشرکین دنیا میں بعض اچھے اعمال کرتے ہیں ۔تو کیا آخرت میں یہ ان کے کام آئیں گے ۔ کیوں؟\nإِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗا لَّسۡتَ مِنۡهُمۡ فِي شَيۡءٍۚ\nاللہ تعالیٰ کے فرمان: (إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗا) (بلا شبہ جن لوگوں نے اپنے دین میں تفرقہ ڈالا اور الگ الگ گروہ بن گئے )اس آیت کے تحت امام مجاہد رحمہ اللہ کہتے ہیں:اس سے مراد اہل بدعات وشبہات ہیں ،کیونکہ وہ ایسے کاموں میں پڑ گئے جو شریعت میں بناؤٹی اور ایجاد کردہ ہیں، اور عقل وفہم کے معیارپر مشکوک اور مشتبہ ہیں۔ (ابن تیمیہ: ۳؍۱۱۷)\nکیا اس آیت کے مصداق اور معنی میں اہل بدعات شامل ہیں؟\nقُلۡ إِنَّنِي هَدَىٰنِي رَبِّيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ دِينٗا قِيَمٗا مِّلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ١٦١ قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ١٦٢\nیہ عموم ہے۔پھر اس کے بعد اللہ تعالیٰ نے دین کے عبادات واعمال میں سب سے زیادہ شرف اور فضیلت والی عبادات کا خصوصی ذکر فرمایا ہے ،ارشاد فرمایا: (قُلۡ إِنَّ صَلَاتِي وَنُسُكِي) کہہ دیجئے کہ میری نماز اور میری قربانی۔ یہ خصوصی ذکر اس لئے ہے کہ یہ دونوں عبادتیں بڑی اونچی شان اور بلند مقام رکھتی ہیں،نیز ان دونوں عبادتوں سے معلوم ہوتا ہے کہ بندہ اللہ تعالیٰ سے محبت رکھتا ہے ۔دین کو اسی کے لئے خالص کرتا ہے اور اپنے دل سے ، زبان سے اوراعضاء وجوارح سے اللہ کی قربت ونزدیکی اختیار کرتا ہے ۔ چونکہ ذبح اور قربانی میں مال خرچ ہوتا ہے جو انسان کے نزدیک محبوب ترین شیء ہے اس لئےاس کا اللہ کے لئے خرچ کرنا اللہ سے محبت کی دلیل ہے ۔ (السعدی: ۲۸۲)\nصلاۃاور قربانیاں پہلی آیت کے معنی میں داخل تھیں۔پھر الگ سے ان کا خصوصی ذکر کیوں کیا گیا؟\nقُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ١٦٢\nیعنی:میرا جینا اور میرا مرنا (لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ) اللہ کے لئے ہی ہے جو تمام جہانوں کا رب ہے۔ یعنی: وہی مجھے زندگی دیتاہے اور موت بھی۔ایک قول میں آیت کایہ معنی بیان کیا گیا ہے کہ: نیک عمل کے ساتھ میرا زندگی گذارنا، او ر جب موت آئے تو اللہ رب العالمین کے لئے ایمان اور یقین کے ساتھ میرا مرنا۔(البغوی: ۲؍ ۸۶)\nجینا اور مرنا کس طرح صرف اللہ رب العالمین کے لئے ہوتاہے؟\nإِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمُۢ ١٦٥\nیہ ترغیب بھی ہے اور ڈراوا بھی کہ جو کوئی اللہ کی نافرمانی کرتا ہے اور اس کے رسولوں کی مخالفت کرتا ہے ،اس کے حق میں اللہ کا حساب کتاب اور عذاب بہت جلد ہوجائیگا۔ اس کے برخلاف جو کوئی اللہ سے دوستی اور تعلق استوار کرتا ہے اور اس کے رسولوں کی لائی ہوئی ہر خبر اور ہر مطالبے کو مانتا ہے ،تو اس کے لئے اللہ تعالیٰ بڑا ہی بخشنے والا نہایت مہربان ہوگا۔ چنانچہ اللہ تعالیٰ اپنے بندوں کو مختلف انداز وبیان کے ذریعہ اپنی طرف بلاتا ہے :کبھی شوق دلاکرجنت کے بیان کے ذریعہ اور اپنے پاس کی نعمتوں کی رغبت دلاکر بلاتا ہے، اور کبھی ڈر و خوف پیدا کرکے جہنم کی آگ کا ذکر کرکے ،اس کی بیڑیوں ،زنجیروں اور سزا وعذاب کو بتاکر نیز قیامت اور اس کی ہولناکیوں کا نقشہ کھینچ کر بندوں کو دعوت دیتا ہے، اور کبھی ان دونوں کے ذریعہ سے اپنے بندوں کو اپنی طرف دعوت دیتا اور بلاتا ہے۔ (ابن کثیر: ۲؍ ۱۹۱)\nدعوت کبھی ڈرادھمکا کر ،کبھی رغبت دلاکر اور کبھی دونوں کے ذریعہ ہوتی ہے۔کیوں؟\nwords\nشِيَعًافرقہ / گروہ.\nقِيَمًاوہ جو دنیا و آخرت کے أمور کے ساتھ قائم ہو.\nوَنُسُكِياور میرا ذبح کرنا.\nوَلاَ تَزِرُاور بوجھ نہیں ڈالا جائے گا.\nوَازِرَةٌگنہگار نفس.\nوِزرَگناہ."],[151,"§الأعراف\ndeeds\nیہ دعا مانگئے: “اَللّٰہُمَّ احْفَظْنِیْ مِن بَینِ يَدَیَّ وَمِنْ خَلْفِیْ وَعَنْ یَّمِینِیْ وَعَنْ شِمالِیْ وَمِنْ فَوقِیْ، وَأَعُوْذُ بِعَظْمَتِكَ أَنْ اُغْتَالَ مِنْ تَحْتِیْ” ۔ اے اللہ! میرے سامنے سے، میرے پیچھے سے،میرے دائیں سے، میرے بائیں سے اور میرے اوپر سے تو میری حفاظت فرما نیز میں تیری عظمت کے ذریعہ اس بات سے پناہ چاہتا ہوں کہ مجھے نیچے سے اچک لیا جائے۔یعنی دھنسا دیا جائے.\nہمیشہ اللہ تعالیٰ کو یاد کرتے رہئے اور خاص طور سے اس وقت جب دوسرے غافل رہتے ہوں.\nآج تنہائی میں اپنے رب سے اپنی زیادتیوں اور خطاؤں کا اعتراف کیجئے ، اورتوبہ کرکے اپنی اصلاح کرلیجئے۔بیشک عذاب آجانے کے بعد گناہوں کا اعتراف کرنے یا توبہ کرنے سے کچھ فائدہ نہیں ہوتا.\nguid\nہمیشہ قرآن کی تلاوت کرنا اور اس میں غور وفکر کرتے رہنا ،نیک اعمال کی یاد دہانی اور ظاہر وباطن کی اصلاح کا بہترین ذریعہ ہے.\nوحی یعنی قرآن وسنت کی اتباع واجب ہے، اور خواہش پرستوں وبدعتیوں کے افکار ونظریات کی پیروی کرنا حرام ہے.\nبے دین اور ظالم حکومتیں تباہ وبرباد ہوگئیں ۔ان کے انجام سے عبرت حاصل کرنی چاہئے.\nrefl\nالٓمٓصٓ ١ كِتَٰبٌ أُنزِلَ إِلَيۡكَ فَلَا يَكُن فِي صَدۡرِكَ حَرَجٞ مِّنۡهُ لِتُنذِرَ بِهِۦ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ ٢\nقرآن کی مختلف سورتوں کے آغاز میں حروف مقطّعات آئے ہیں، جیسے یہاں(الٓمٓصٓ)ہے۔ایسی ہر جگہ ان حروف کے بعد یا تو قرآن کا ذکر کیا گیا ہے یا وحی کا،یا پھر ان دونوں کی ہم معنی چیز کا ذکر آیا ہے ،اس بنیاد پر یہ قول راجح معلوم ہوتا ہے کہ ان حروفِ تہجی کا مقصد ہے : اہل عرب کو چیلنج دینا اور کھلا اعلان کرنا کہ تم قرآن کے جیسا کلام کبھی نہیں لاسکتے ۔ (ابن عاشور: ۸؍۱۰)\nقرآن میں حروف مقطعات کے بعد زیادہ تر(كِتَٰبٌ)یعنی قرآن کا ذکر کیوں آتا ہے؟\nٱتَّبِعُواْ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡ وَلَا تَتَّبِعُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۗ قَلِيلٗا مَّا تَذَكَّرُونَ ٣\nآیت اس بات پر دلالت کرتی ہے کہ نص یعنی قرآن وحدیث کی واضح دلیل کی موجودگی میں لوگوں کی رائے اور قیاس کی اتباع چھوڑ دینی چاہئے ۔یعنی اللہ اور رسول اللہ صلی اللہ علیہ وسلم کے فرمان کے سامنے کسی کا قول قبول یا اختیار نہیں کرنا چاہئے۔(القرطبی: ۹؍۱۵۱)\nلوگوں کے افکار اور آراء کی وجہ سے دلیل یعنی قرآن وحدیث کو چھوڑدینے والے کے لئے قرآن کی کیارہنمائی ہے؟\nوَكَم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا فَجَآءَهَا بَأۡسُنَا بَيَٰتًا أَوۡ هُمۡ قَآئِلُونَ ٤\nیعنی: ان میں سے کچھ لوگ ایسے ہیں کہ اللہ کے فیصلہ ،اس کے سخت عذاب اور انتقامی سزا نے انہیں (بَيَٰتًا) رات کے وقت آدبوچا۔ (أَوۡ هُمۡ قَآئِلُون) یا اس حالت میں جبکہ وہ دوپہر کے وقت آرام میں تھے ۔ (قَآئِلُون) قیلولہ سے بنا ہے ،جس کے معنی ہیں: دن کے درمیانی حصے یعنی دوپہر کے وقت آرام کرنا۔عذابِ الٰہی آنے کے یہ دونوں اوقات غفلت وبے خبری کے وقت ہیں۔ (ابن کثیر: ۲؍ ۱۹۲)\nرات اور دوپہر کے دو وقت عذاب نازل ہونے کے لئے خاص کیوں کئے گئے؟\nفَمَا كَانَ دَعۡوَىٰهُمۡ إِذۡ جَآءَهُم بَأۡسُنَآ إِلَّآ أَن قَالُوٓاْ إِنَّا كُنَّا ظَٰلِمِينَ ٥\nان کاجھٹلانا ظلم قرار دیا گیا ہے۔ اس لئے کہ یہ ایسی چیز کوجھٹلاناتھا جس کے سچ ہونے پر بہت سے ثبوت موجود تھے اور دلیلیں قائم ہوچکی تھیں، لہذا ایسے سچ کو جھٹلانا سچائی کی دلیلوں پر ظلم ہے ۔ (ابن عاشور: ۸؍۳۲)\nجس چیز کی سچائی پر دلائل آچکے ہوں ،ایسی چیز کو جھٹلانا ظلم کی ایک قسم ہے ۔اس کی وضاحت کیجئے.\nفَلَنَسۡـَٔلَنَّ ٱلَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ وَلَنَسۡـَٔلَنَّ ٱلۡمُرۡسَلِينَ ٦\nاہل علم یعنی اہل کتاب و سنت کا اس بات پر اتفاق ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے علاوہ کوئی بھی شخصیت ہو ،اس کے قول کو لیا بھی جاسکتا ہے اور چھوڑا بھی جاسکتا ہے ۔صرف رسول اللہ صلی اللہ علیہ وسلم کا معاملہ اور حیثیت اس قاعدے سے الگ اور مستثنیٰ ہے، کیونکہ آپ صلی اللہ علیہ وسلم کی بیان کردہ ہر خبر کو سچ ماننااور آپ کا ہر حکم بجالاناواجب اورضروری ہے ۔ اس لئے کہ آپ صلی اللہ علیہ وسلم ایسے معصوم تھے جو اپنی خواہش سے کوئی بات نہیں کہتے۔ ان کی کہی ہوئی ہر بات وحی ہوتی ہے جو اُن پر اتاری جاتی ہے، اور آپ صلی اللہ علیہ وسلم ہی ایسی شخصیت ہیں جن کے بارے میں قیامت کے دن لوگوں سے سوال اور پوچھ تاچھ ہوگی ۔جیسا کہ اللہ تعالیٰ نے فرمایا ہے: (فَلَنَسَۡٔلَنَّ ٱلَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ وَلَنَسَۡٔلَنَّ ٱلۡمُرۡسَلِينَ) پھر ہم ان لوگوں سے ضرور باز پرس اور پوچھ تاچھ کریں گے جن کی طرف پیغمبر بھیجے گئے تھے، اور ہم پیغمبروں سے بھی ضرور پوچھیں گے ۔ (ابن تیمیہ: ۳؍۱۳۷)\nناپسندیدہ تعصب کا ایک علاج اس بات کا علم اور یقین ہے کہ “رسول اللہ صلی اللہ علیہ وسلم کے سوا ہر شخص کی بات مانی بھی جاسکتی ہے اور چھوڑی بھی”،اس حقیقت کی وضاحت کیجئے.\nوَٱلۡوَزۡنُ يَوۡمَئِذٍ ٱلۡحَقُّۚ فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ٨\nاگر آپ یہ اعتراض یا سوال کریں کہ : اللہ عزوجل بندوں کے اعمال کی مقدار اور وزن سے پوری طرح واقف ہے۔تو پھر ان اعمال کوتولنے میں کیا حکمت ہے؟ تو میں اس کے جواب میں کہوں گا کہ :اس میں کئی حکمتیں ہیں: ایک مقصد ہے عدل وانصاف کا اظہار کرنا کہ اللہ عزوجل اپنے بندوں پر ظلم قطعی نہیں کرتا۔اسی طرح ایک حکمت یہ بھی ہے کہ بندوں کو ان کے خیر وشر اور بھلائی وبرائی سے آگاہ کردینا وغیرہ۔ (القاسمی: ۱؍ ۲۹۷)\nاعمال وزن کرنے کی کیا حکمت ہے جبکہ اللہ تعالیٰ ان کے بارے میں پوری جانکاری رکھتا ہے؟\nوَلَقَدۡ خَلَقۡنَٰكُمۡ ثُمَّ صَوَّرۡنَٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ لَمۡ يَكُن مِّنَ ٱلسَّٰجِدِينَ ١١\nاللہ تعالیٰ اس مقام پر آدم علیہ السلام کے بیٹوں ۔انسانوں۔کو ان کے باپ آدم علیہ السلام کے شرف وعزت سے آگاہ کررہا ہے ،نیز ان کے دشمن ابلیس کی دشمنی کو اجاگر کررہا ہے ،ساتھ ہی یہ بھی بیان کررہا ہے کہ یہ دشمن ان کے اور ان کے باپ کے حق میں کس قدر حسد میں مبتلا ہے،تاکہ وہ اس سے ہوشیار وخبردار رہیں، اور اس کے طور طریقوں کی پیروی نہ کریں۔ (ابن کثیر: ۲؍۲۹۳)\nابلیس نے انسانوں کے باپ آدم علیہ السلام کو سجدہ نہیں کیا تھا۔مسلمانوں کو اس بات سے کیا سبق ملتا ہے؟\nwords\nبَأسُنَاہمارا عذاب.\nبَيَاتًارات کو سوتے ہوئے.\nقَائِلُونَآدھے دن کو سوتے ہوئے.\nوَالوَزنُبندوں کے اعمال کا وزن.\nمَعَايِشَجس سے تم زندگی کی گزران کرو."],[152,"§الأعراف\ndeeds\nآج کوئی ایسا کام کیجئے جس میں دوسروں کے ساتھ عاجزی و انکساری اورکبر وغرور سے دوری نمایاں ہو.\nایسی خوبیوں اور نعمتوں کو یاد کیجئے جن میں اللہ نے آپ کو دوسروں سے ممتاز کیا ہے۔ پھر ان خوبیوں کو اللہ وحدہ کی طرف منسوب کیجئے.\nآج بکثرت شیطانِ مردود سے اللہ تعالیٰ کی پناہ مانگئے ۔ اور یہ دعا بھی خوب پڑھئے: “اَللّٰہُمَّ احْفَظْنِیْ مِن بَینِ يَدَیَّ وَمِنْ خَلْفِیْ وَعَنْ یَّمِینِیْ وَعَنْ شِمالِیْ وَمِنْ فَوقِیْ، وَأَعُوْذُ بِعَظْمَتِكَ أَنْ اُغْتَالَ مِنْ تَحْتِیْ” ۔ اے اللہ! میرے سامنے سے،پیچھے سے،میرے دائیں سے،بائیں سے اور میرے اوپر سے تو میری حفاظت فرما ،نیز میں تیری عظمت کے ذریعہ اس بات سے پناہ چاہتا ہوں کہ مجھے نیچے سے اچک لیا جائے۔یعنی دھنسا دیا جائے.\nguid\nآدم علیہ السلام اور ابلیس کا یہ واقعہ پوری تاکید سے یہ واضح کرتا ہے کہ اس دشمن نے آپ کے خلاف پوری تیاری کررکھی ہے چنانچہ آپ بھی اس کے وار ناکام بنانے کے لئے خوب تیاری کرلیجئے.\nابلیس جن ہتھیاروں سے انسان کے خلاف جنگ کرتا ہے وہ دلوں میں وسوسے ڈالنے اور برائیوں کو اچھا بناکر پیش کرنے کے علاوہ کچھ اور نہیں ہے.\nاللہ تعالیٰ کی قسمیں کھاکر خیر خواہی کا دعوی کرنے والا ہر شخص سچا نہیں ہوتا۔ قسم کھانے والے کا ماضی اور اس کی تاریخ اس کی حقیقت بیان کرتے ہیں.\nrefl\nقَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ١٢\n(قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ) ابلیس نے کہا:میں آدم سے بہتر ہوں۔ یہ وہ علت و سبب ہے،جسے ابلیس نے سجدہ نہ کرنے کی بنیاد بنایا،جبکہ اس کا سیدھا مطلب اللہ تعالیٰ کی ذات پر اعتراض ہے کہ اس کے خیال میں اللہ نے فاضل یعنی اونچے درجہ والے کو مفضول یعنی کمتر درجہ والے کو سجدہ کرنے کا حکم دے دیا۔اور اس اعتراض کی بناپر ابلیس کافر ہوگیا، کیونکہ اس کا کفر “کفرِ جُحود” یعنی اللہ کا انکار کرنے والا کفر نہیں تھا ۔ (ابن جُزی: ۱؍ ۲۹۷)\nکبھی ایسا ہوتا ہے کہ انسان اپنی عقل فہم کے غرور میں اس درجہ تک پہنچ جاتا ہے کہ اللہ کی شریعت پر اعتراض کربیٹھتا ہے ۔اس رویے اور عمل کے نتیجے میں وہ کفر کربیٹھتا ہے۔آیت کی روشنی میں اس کی وضاحت کیجئے.\nقَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ١٢\nابلیس کے اس قول میں پیش کی گئی حجت ودلیل کہ: (أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ) میں آدم سے بہتر ہوں کہ تو نے مجھے آگ سے پیدا کیا اور اسے مٹی سے ۔ یہ غلط دلیل تھی اس لئے کہ اس نے نص یعنی حکم الٰہی کے مقابلے میں قیاس کو پیش کیا تھا ۔(ابن تیمیہ: ۳؍ ۱۸۳)\nابلیس کی دلیل باطل کیوں تھی؟\nخَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ١٢\nابلیس نے آگ کے عنصر کو مٹی اور گارے کے عنصر سے بہتر وبرتر ٹھہراکر غلط بات کہی، کیونکہ مٹی کے عنصر میں عاجزی اور جھکنے کی خاصیت ہے ،سکون اور ٹھہراؤ ہے ،صبر وبردباری اور وقار کی خوبی ہے ۔نیز اسی مٹی سے زمین کی برکتیں اور نعمتیں حاصل ہوتی ہیں۔ جیسے پیڑ اوردرخت ، طرح طرح کے پودے اور نباتات جو مختلف حصوں میں الگ الگ جنس اور قسم کے ہوتے ہیں ۔جبکہ آگ کا معاملہ اس کے برخلاف ہے ،اس میں ہلکاپن ہے ، جوش اور طیش ہے، یعنی بھڑکنے کی صفت اور جلا دینے کی خاصیت ہے ۔ (السعدی: ۲۸۴)\nابلیس نے آگ کے عنصر کو مٹی کے عنصر پربرتری دے کر غلطی کی ۔اُس کی اِس خطا اور غلطی کی وجہ کیا تھی؟\nقَالَ فَٱهۡبِطۡ مِنۡهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ ١٣\n(فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا) تجھے یہ حق حاصل نہیں کہ تو آسمان یا جنت میں رہ کر تکبر کرے، کیونکہ یہاں وہ فرشتے بستے ہیں جن کا شیوہ عاجزی و انکساری ہے۔ (فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ) سو یہاں سے نکل جا! یقیناًتو ذلیل لوگوں میں سے ہے۔ مراد ہے : ذلیل ترین لوگوں میں سے۔ یہ اس بات کی دلیل ہے کہ جو شخص اپنے مالک ومولیٰ کی نافرمانی کرتا ہے وہ ذلیل ہے ۔ (القرطبی: ۹؍۱۶۹)\nاللہ کے مقرب بندوں کی کیا صفت ہے اور اس سے دور رہنے والوں کی پہچان کیا ہے؟\nفَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ ١٣\n(فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ) سو نکل جا! تو ان لوگوں میں سے ہے جن کی عزت ووقعت نہیں۔ یعنی ذلیل ورسوا اور حقیر وبے حیثیت لوگوں میں سے ہے۔ ابلیس کے ساتھ یہ معاملہ اس کی منشااور ارادے کے بالکل الٹ تھا ۔اس کی چاہت تھی بڑائی اور تکبر۔ لہذا اس چاہت کی سزا اس کی ضد یعنی ذلت کی شکل میں دے دی گئی۔ (ابن کثیر: ۲؍ ۱۹۵)\nابلیس کا انجام ذلت اور بے عزتی کیوں ہوا؟\nثُمَّ لَأٓتِيَنَّهُم مِّنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَيۡمَٰنِهِمۡ وَعَن شَمَآئِلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَٰكِرِينَ ١٧\nاللہ تعالیٰ نے اس آیت میں ابلیس کی جو بات نقل کی ہے کہ : (ثُمَّ لَأٓتِيَنَّهُم مِّنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَيۡمَٰنِهِمۡ وَعَن شَمَآئِلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَٰكِرِينَ )پھر میں بہکانے اوربھٹکانے کے لئے ضرور ان کے پاس آؤنگا:ان کے سامنے سے ،پیچھے سے ،داہنے سے اور بائیں جانب سے بھی ۔ اور تو ان میں سے زیادہ تر لوگوں کو شکر گذار نہیں پائیگا۔ اس قول کے بارے میں حضرت ابن عباس رضی اللہ عنہما اور عکرمہ رحمہ اللہ کہتے ہیں کہ : ابلیس نے یہاں“مِنْ فَوْقِہِمْ” (یعنی ان کے اوپر سے بھی آؤں گا) نہیں کہا۔اس لئے کہ اسے معلوم تھا کہ ان کے اوپر اللہ تعالیٰ کی ذات ہے۔ (ابن تیمیہ: ۳؍۱۴۰)\nاللہ تعالیٰ نے ابلیس کا جو قول نقل کیا ہے اس میں “مِنْ فَوْقِہِمْ” یعنی ان کے اوپر کی جانب سے کیوں نہیں کہا؟\nفَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا\n(مِنْ سَوۡءَٰتِهِمَا ) یعنی“مِنْ عَوْرَاتِهِمَا” جس کا معنی ہے: ان کی شرم گاہیں۔ شر م گاہ کو “عَورَۃ ” اور “سَوْأَۃ” کا نام اس لئے دیا گیا ہے کیونکہ آدمی کو اس کا کھلنا اور ظاہر ہونا برا لگتا ہے ۔ اس بات سے معلوم ہوا کہ شرم گاہ کا کھلا رکھنابرا اور قبیح ہے۔(القرطبی: ۹؍۱۷۵)\nشرم گاہ کو “عَورَۃ ” اور“سَوْأَۃ” کا نام دینا کس چیز پر دلالت کرتا ہے؟\nwords\nالصَّاغِرِينَذلیل و حقیر.\nمَذؤومًامذموم / غضب کا شکار.\nمَدحُورًاراندہء درگاہ.\nوَطَفِقَااوروہ شروع کرنے لگے.\nيَخصِفَانِجوڑ جوڑ کر رکھنے لگے."],[153,"§الأعراف\ndeeds\nاپنے کئے ہوئے کسی گناہ کو یاد کیجئے اورپھر آج ہی ستر بار اللہ تعالیٰ سے توبہ و استغفار کیجئے.\nآج قبولیت کے اوقات میں یہ عظیم دعا مانگئے بیشک یہ اللہ کے مقرَّب بندوں کی دعاؤں میں سے ایک ہے.\nفرض نمازیں پابندی کے ساتھ ہمیشہ مسجد میں ہی ادا کیجئے.\nguid\nاگر گناہگار کو اللہ کی رحمت اور مغفرت کا سہارا نہ ملے تو وہ یقیناًنقصان ہی اٹھائیگا.\nیقیناًوہ گناہ کی نحوست ہی تھی جو ابلیس کو اللہ کی رحمت سے دور کردیئے جانے، اور آدم علیہ السلام کے جنت سے نکالے جانے کا سبب بنی، اس لئے آپ گناہوں سے ہوشیار رہئے.\nشیطان سے چوکنا رہئے اور ان جگہوں سے غفلت نہ برتئے جہاں سے وہ آپ پر حملہ کرسکتا ہے.\nrefl\nقَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ٢٣\nبعض بزرگوں نے کہا کہ :دولوگوں نے گناہ کا ارتکاب کیا:آدم علیہ السلام نے اور ابلیس نے ۔ آدم علیہ السلام نے تو اپنے گناہ سے توبہ کرلی چنانچہ اللہ نے نہ صرف ان کی توبہ قبول کی بلکہ انہیں نبوت کے لئے چن لیا اورہدایت سے نواز دیا ۔جبکہ ابلیس گناہ کرکے اڑ گیا اور تقدیر کے ذریعہ اپنے گناہ کے جواز میں حجت پیش کی ۔لہذا اب جو شخص اپنے گناہ سے توبہ کرتا ہے ،وہ اپنے باپ آدم علیہ السلام کی مشابہت اختیار کرتا ہے، اور جوکوئی گناہ پر اڑ جاتا ہے اور اس پر تقدیر کو دلیل بناتا ہے وہ ابلیس کے جیسا ہے ۔(ابن تیمیہ: ۳؍ ۱۴۲)\nگناہ کافوراً اعتراف کرلینا اور اس پر معافی مانگ لینافضیلت والا عمل ہے ۔آیت کی روشنی میں بیان کیجئے.\nقَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ٢٣\nمغفرت کا مطلب ہے برائیوں کو مٹانااور رحمت سے مراد ہے بھلائیوں کو اتارنا۔ (ابن تیمیہ: ۳؍ ۱۴۲)\nآیت کریمہ میں مذکور مغفرت اور رحمت کے درمیان کیا فرق ہے؟\nقَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ٢٣\nگناہوں کے سرزد ہوجانے کے بعد جو شخص حضرت آدم علیہ السلام کی طرح گناہ کا اعتراف کرلے ، مغفرت طلب کرے، نادم و شرمندہ ہواور گناہ سے دامن جھٹک کر باز آجائے تو نتیجے میں اللہ تعالیٰ اسے چن لیتا ہے او ر ہدایت سے نواز کر سیدھے راستے پر ڈال دیتا ہے ۔ لیکن گناہ کا ارتکاب کرلینے کے بعد جو شخص ابلیس کے جیسا طور طریقہ اپناتا ہے وہ نافرمانیوں میں بڑھتا چلاجاتا ہے ،گناہ پر گناہ کرتا جاتا ہے تو ایسے شخص کو اللہ سے دوری میں اضافہ کے علاوہ کچھ نہیں ملتا۔ (السعدی: ۲۸۵)\nگناہ میں پڑجانے والے شخص کے لئے آدم علیہ السلام اور ابلیس کے قصے میں بہت بڑا سبق ہے ۔وہ کیا ہے؟\nوَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٞۚ\nتقوے کا لباس حسی اور ظاہری لباس سے بہت بہتر ہے ۔اس لئے کہ تقوے کا لباس بندے کے ساتھ ہمیشہ اور ہر وقت رہتا ہے جو نہ پرانا اور بوسیدہ ہوتا ہے اور نہ برباد ہوتا ہے ۔نیز یہ لباسِ تقویٰ قلب وروح کی زینت اور خوبصورتی ہے۔ رہا ظاہری لباس تو اس کا زیادہ سے زیادہ فائدہ یہ ہے کہ یہ ظاہری وجسمانی ستر ڈھانپتا ہے وہ بھی ہمیشہ نہیں ، صرف محدود مدت اور کچھ وقت تک۔یا پھر یہ لباس انسان کے لئے خوبصورتی کا ذریعہ بنتا ہے اس سے ہٹ کر اس لباس کا کوئی فائدہ نہیں ہوتا۔ (السعدی: ۲۸۶)\nتقوے کا لباس ظاہری لباس سے بہتر کیوں ہے؟\nإِنَّهُۥ يَرَىٰكُمۡ هُوَ وَقَبِيلُهُۥ مِنۡ حَيۡثُ لَا تَرَوۡنَهُمۡۗ\nمالک بن دینار رحمہ اللہ کہتے ہیں کہ :یقیناًوہ دشمن جو تمہیں دیکھ رہا ہے اور تم اسے نہیں دیکھ سکتے ،اس کی لڑائی ،حملہ اور وار بہت ہی سخت ہوں گے۔ سوائے اس کے جسے اللہ محفوظ رکھے۔ (البغوی: ۲؍۹۷)\nاس دشمن کا خطرہ بیان کیجئے جو آپ کو دیکھ رہا ہے لیکن آپ اسے نہیں دیکھ پاتے؟\nإِنَّا جَعَلۡنَا ٱلشَّيَٰطِينَ أَوۡلِيَآءَ لِلَّذِينَ لَا يُؤۡمِنُونَ ٢٧\nیعنی: ان بے ایمان لوگوں کی سزا میں زیادتی کے طور پرہم نے حق سے دور ہونے میں ان کے درمیان برابری کردی، یعنی: انہیں اور شیاطین کو ایک جیسا بنادیا۔ (القرطبی: ۹؍۳۹۳)\nشیطانوں کے دوست اور رفیق کون لوگ ہیں؟\nإِنَّهُمُ ٱتَّخَذُواْ ٱلشَّيَٰطِينَ أَوۡلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ٣٠\nآیت میں اس بات کی دلیل ہے کہ ہدایت اللہ کے فضل واحسان سے ملتی ہے ۔ اور گمراہی کی وجہ یہ ہوتی ہے کہ اللہ تعالیٰ بندے کی مدد چھوڑدے۔اور اللہ تعالیٰ بندے کو اپنی مدد اور توفیقِ ہدایت سے اس وقت محروم کرتا ہے جب بندہ اپنی جہالت اور ظلم کی بناپر شیطان سے دوستی گانٹھ لیتا ہے، اور اپنی ذات کے لئے خود ہی گمراہی کا سبب بنتاہے۔ اور جو شخص گمراہ ہوتے ہوئے خود کوہدایت یاب سمجھے تو اس کے لئے کوئی عذر نہیں ہوگا۔ (السعدی: ۲۸۷)\nاکثر گمراہ اور بدعتی لوگ یہ عقیدہ رکھتے ہیں کہ وہ حق پر ہیں ،تو کیا یہ یقین انہیں فائدہ دیگا؟\nwords\nيُوَارِي سَوآتِكُموہ چھپائے تمہاری شرمگاہوں کو / ضرورت کا لباس.\nوَرِيشًازینت کا لباس.\nيَفتِنَنَّكُمُوہ ضرور تمہیں گمراہ کرے گا/ دھوکا دے گا.\nبِالقِسطِعدل کے ساتھ."],[154,"§الأعراف\ndeeds\nاس آیتِ کریمہ پر عمل کرنے کی نیت سے آج نماز کے لئے اچھی طرح تیار ہوکر جائیے.\nآیت کریمہ میں ممنوعہ امور کے اصول بیان کئے گئے ہیں ۔آپ پیغام ترتیب دے کر لوگوں کو ان سے آگاہ کیجئے.\nعوام کو پیغام کے ذریعہ بلا علم فتوی دینے یا اللہ کی جانب کوئی بات منسوب کردینے سے خبردار کیجئے.\nguid\nکھانے ،پینے یا دوسرے مالی اخراجات میں فضول خرچی سے بچئے، کیونکہ اللہ تعالیٰ فضول خرچی کرنے والوں کو پسند نہیں فرماتاہے.\nکوئی چیز جو آپ کو اچھی نہ لگتی ہو، اورکوئی چیزجسے اللہ سبحانہ وتعالیٰ نے حرام کیا ہو ،دونوں میں فرق ہے۔ اللہ کی حلال کی ہوئی کسی چیز کو حرام قرار دینا کسی کے لئے جائز نہیں ہے.\nامت کا معاملہ افراد کی مانند ہے ۔ جب امت کے اکثر افراد گناہ میں مبتلا ہوجائیں تو پوری امت ہلاک ہوجاتی ہے، ویسے ہی جیسے جسم کے اکثر حصوں میں بیماری پھیل جانے پر فرد ہلاک ہوجاتا ہے.\nrefl\nيَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ ٣١\nاس آیت کی تفسیر میں ایک بات یہ کہی گئی ہے کہ یہاں زینت سے مراد وہ زینت ہے جو عام لباس اور سترپوشی سے زائد ہوتی ہے، جیسے جمعہ کے لئے اچھے سے اچھا لباس پہن کر ،مسواک کرکے، اور خوشبولگاکر زیب وزینت اختیار کرنا۔ (وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ) اور کھاؤ،پیو مگر حد سے نہ گذر جاؤ۔یقیناًاللہ حدسے آگے نکل جانے والوں کوپسند نہیں کرتا۔ یعنی : کھانے میں اعتدال سے کام لو۔ جتنی ضرورت ہو اس سے زیادہ مت کھاؤ۔ اطباء کا کہنا ہے کہ :اس آیت کریمہ (وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ) میں پوری کی پوری طب یعنی علاج معالجے کا علم اور اس کی تفصیل سمیٹ دی گئی ہے ۔ (ابن جزی: ۱؍۳۰۰)\nاس آیت نے جسم ودل دونوں کی اصلاح کے نسخے کوسمیٹ لیا ہے ۔ اس بات کی وضاحت کیجئ.\nقُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ٣٢\nیہ اللہ کی طرف سے بندوں کو کشادگی اورچھوٹ دی گئی ہے کہ پاکیزہ چیزوں میں سے جو چاہیں استعمال کریں ۔ اللہ نے یہ سہولت اس لئے دی ہے تاکہ بندے اس کے ذریعہ اس کی عبادت میں مدد لیں۔چنانچہ اسے صرف اپنے مومن بندوں کے لئے جائز ومباح کیا ہے اور اسی لئے فرمایا ہے: (قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ)آپ کہہ دیجئے کہ یہ چیزیں دنیا کی زندگی میں ان لوگوں کے لئے ہیں جو ایمان لائے، اور قیامت کے دن تو خالصۃً یعنی صرف اور صرف انہی کے لئے ہوں گی۔ یعنی: ان نعمتوں کے بارے میں ان پر کوئی تاوان یا بدلہ عائد نہیں ہوگا۔اور آیت کے معنی کا مفہومِ مخالف یہ ہے کہ جو لوگ اللہ پر ایمان نہیں رکھتے بلکہ اللہ کی دی ہوئی ان نعمتوں اور پاکیزہ چیزوں سے اس کی نافرمانیوں میں مدد لیتے ہیں تو یہ نعمتیں نہ ان کے لئے خالص اور نہ خاص ہیں اور نہ ہی جائز ومباح، بلکہ ان سے لطف ولذت اٹھانے پر ان کو سزا دی جائیگی، اور قیامت کے دن نعمتوں کے بارے میں ان سے باز پرس ہوگی ۔ (السعدی: ۲۸۷)\nمومنوں کے لئے (وَٱلطَّيِّبَٰتِ) یعنی پاکیزہ چیزوں کو حلال کرنے کی کیا حکمت ہے؟\nقُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ٣٢\nآیت میں دلیل ہے کہ محفلوں میں،تقریبات میں ،تہواروں کے موقع پر،لوگوں سے ملاقات کے وقت اور دوستوں ،بھائیوں کی زیارت کی مناسبت سے اونچے اور اعلیٰ قسم کے لباس پہن کر آراستہ ہوسکتے ہیں۔ (القرطبی: ۹؍۲۰۳)\nاللہ تعالیٰ خوبصورت ہے اور خوبصورتی کو پسندفرماتا ہے ۔اس بات کو آیت کی روشنی میں واضح کیجئے.\nقُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ\nقیامت کے دن مومنوں کو یہ نعمتیں اس طرح خالص اور بے میل ملیں گی کہ اس میں کوئی ناپسندیدہ اور مزہ خراب کرنے والی چیز ہوگی نہ غم اور فکر ہوں گے۔ جبکہ دنیا میں انہیں یہ نعمتیں بہت سی ناپسندیدہ چیزوں، آلودگیوں،کدورتوں اور غموں کے ساتھ ملتی ہیں۔ (البغوی: ۲؍۱۰۰)\n“متاعِ حَسن” یعنی لذت کے سامان اور اچھی چیزیں قیامت کے روز مومنوں کے لئے کس طرح خالص ہوں گی؟\nكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ٣٢ قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ\n(كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ) ہم اسی طرح آیات کو صاف صاف بیان کرتے ہیں۔ یعنی انہیں اچھی طرح واضح کردیتے ہیں اور آیتوں کو کھول کھول کر بیان کردیتے ہیں۔ (لِقَوۡمٖ يَعۡلَمُونَ)ان لوگوں کے لئے جو علم رکھتے ہیں۔ اس لئے کہ اللہ نے جن آیتوں کو وضاحت اور تفصیل کے ساتھ پیش فرمادیا ہے ،ان سے یہی علم والے فائدہ اٹھاتے ہیں اور یہی لوگ یہ علم اور یقین رکھتے ہیں کہ یہ آیتیں اللہ کی طرف سے ہیں، لہذا ان میں سنجیدگی سے غور وفکر کرتے ہیں اور اچھی طرح سمجھتے بوجھتے ہیں۔ اس کے بعد اللہ تعالیٰ نے ان حرام چیزوں کا ذکر فرمایا ہے جنہیں اس نے تمام شریعتوں میں حرام قراد دیا ہے ،چنانچہ فرمایا: (قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ) آپ کہہ دیجئے کہ :میرے رب نے جو حرام کیا ہے وہ تو یہ ہیں:بے حیائی کے کام جو کھلے ہوں اور جو چھپے ہوں۔فواحش سے مراد وہ بڑے بڑے گناہ ہیں جن کی برائی اور خرابی ظاہر ہو، اسی وجہ سے انہیں بہت برا اور قبیح (گھناؤنا اور معیوب)سمجھاجاتا ہے جیسے زناکاری اور عمل قوم لوط (اغلام بازی) وغیرہ۔ (السعدی: ۲۸۷)\nآیتوں کو تفصیل سے اور صاف صاف بیان کرنے کی بات علم وسمجھ رکھنے والوں کے ساتھ خاص کیوں کی گئی ہے؟\nقُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡيَ بِغَيۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ٣٣\nحرام چیزوں کی بنیادیں اوراصول یہ وہ چیزیں ہیں جن کے بارے میں اللہ تعالیٰ کا ارشاد ہے: (قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡيَ بِغَيۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ) آپ ان سے کہئے میرے رب نے جو کچھ حرام ٹھہرایا ہے وہ تو یہ ہیں: بے حیائی کے کام ،ان میں سے جو کھلے ہوں اور جو چھپے ہوں،گناہ کے کام ،ناحق ظلم وزیادتی، اور یہ کہ تم اللہ کے ساتھ کسی کو شریک بناؤ جس کی اس نے کوئی سند نہیں اتاری ،نیز یہ کہ تم اللہ کے ذمہ ایسی بات کہوجس کا تمہیں علم نہیں۔ آیت میں ذکر کردہ یہ چیزیں حرام چیزوں کی جڑاور اصل ہیں۔ جن کے حرام ہونے پر تمام انبیاء کرام علیہم السلام کی شریعتیں متفق ہیں۔(ابن تیمیہ: ۳؍۱۵۷)\nآیت کریمہ کے مطابق “اصول محرمات” یعنی حرام چیزوں کی بنیادیں کون کون سی چیزیں ہیں؟\nقُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ\nچیزوں میں برائی اور اچھائی کا معیار شریعت ہے ۔شریعت کی رو سے ہی یہ بات معلوم ہوگی کہ کون سی چیز بری ہے اور کون سی اچھی۔بالکل یہی معاملہ فحش چیز یعنی بے حیائی کا ہے کہ اس کے بارے میں شریعت کا فیصلہ ہی لیا جائیگا، چنانچہ اللہ تعالیٰ نے یہاں جو(ٱلۡفَوَٰحِشَ) کہا ہے تو اس میں یہی اشارہ ہے کہ فواحش سے مراد وہی چیزیں ہیں جن کا حرام ہونا شریعت نے دوسری جگہوں پر صاف صاف بیان کردیا ہے ۔ خلاصہ یہ ہوا کہ ہر وہ چیز جسے شریعت نے حرام قرار دیا ہے وہ فحش چیزہے، گرچہ عقل اسے برا نہ سمجھے۔ جیسے مردوں کے لئے ریشم کا کپڑا پہننا،اور سونا استعمال کرنا وغیرہ۔(ابن عطیہ۲؍۳۹۵)\nحلال اور حرام ٹھہرانے میں اثر انداز ہونے والی اچھائی اور برائی کا پیمانہ کیا ہے؟\nwords\nزِينَتَكُمتمہاری شرمگاہ چھپانے والا/ تمہارے لیے زینت.\nنَصِيبُهُمان کا حصہ.\nمِنَ الكِتَابِجو ان پر لوح محفوظ میں عذاب لکھ دیا گیا."],[155,"§الأعراف\ndeeds\nلعنت بھیجنا جہنمیوں کی صفات میں سے ہے ۔آپ پیغام بھیج کر لوگوں کو اس سے باز رہنے کی تلقین کیجئے.\nگھر سے نکلتے وقت یہ دعاپڑھئے: “اَللّٰہُمَّ اِنِّیْ أَعُوْذُ بِكِ أَنْ أَضِلَّ أَوْ اُضَلَّ أَوْ أَزِلَّ أَوْ اُزَلَّ أوأَظْلِمَ أَوْ اُظلَمَ أَوْ أَجْہَلَ أَوْ يُجْہَلَ عَلَیَّ”۔میں گمرا ہ ہوجاؤں یا گمراہ کردیا جاؤں، پھسل جاؤں یا پھسلا دیا جاؤں،میں ظلم کروں یا مجھ پر ظلم کیا جائے ،میں جہالت کا کام کروں یا میرے ساتھ جہالت برتی جائے۔ اے اللہ ! میں ان سب باتوں سے تیری پناہ مانگتا ہوں.\nاپنے آس پاس والوں کو دل کی صفائی کی اہمیت بتائیے، اور انہیں بتائیے کہ دل کوصاف رکھنا جنتیوں کی صفات میں سے ہے.\nguid\nقیامت کے دن برے دوست ایک دوسرے پر لعنت بھیجیں گے، کیونکہ وہ سبھی ایک دوسرے کے عذاب کا سبب بنے ہوں گے.\nاگر آپ کسی مال ومنصب والے کی گمراہی میں پیروی کریں گے تو وہ قیامت کے دن آپ کے کام نہیں آئیگا۔اس کے برخلاف وہ تو آپ سے لاتعلقی ظاہر کردیگا.\nاللہ کی شریعت کی پابندی بہت ہی آسان اور قابلِ عمل ہے، اس لئے آپ اللہ سے مدد مانگئے اورعاجز نہ بنئے.\nrefl\nقَالَ ٱدۡخُلُواْ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِكُم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِ فِي ٱلنَّارِۖ كُلَّمَا دَخَلَتۡ أُمَّةٞ لَّعَنَتۡ أُخۡتَهَاۖ حَتَّىٰٓ إِذَا ٱدَّارَكُواْ فِيهَا جَمِيعٗا قَالَتۡ أُخۡرَىٰهُمۡ لِأُولَىٰهُمۡ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمۡ عَذَابٗا ضِعۡفٗا مِّنَ ٱلنَّارِۖ قَالَ لِكُلّٖ ضِعۡفٞ وَلَٰكِن لَّا تَعۡلَمُونَ ٣٨\nاللہ تعالیٰ نے مختلف امتوں کے سرداروں اور ان کے پیروکاروں کے بیچ آخرت میں ہونے والی بات چیت اور تکرار کو بیان کیا ہے ۔اس میں مسلمان قائدین اوررہنماؤں کے لئے نصیحت اور سبق ہے ۔ساتھ ہی ان کے لئے اس بات سے تنبیہ اور ڈراوا بھی ہے کہ وہ اپنے پیچھے چلنے والوں کو ایسے کاموں میں لگادیں جو انہیں گمراہی کی کھائی میں گرادیں، اور ان کی خواہشات اور من مانی چیزوں کو حسین بناکر پیش کریں۔ اسی طرح آخرت اور جہنم کی اس بحث وتکرار میں عام مسلمانوں کے لئے بھی وعظ ونصیحت ہے کہ ہر اس شخص کی تائید میں پسیج نہ جائیں اور نہ ہی نرم پڑجائیں جو اُن کی خواہشاتِ نفس اورمن مانیوں کی موافقت کرے،مگر ان تک نصیحت کی باتیں پہنچنے نہ دے۔ (ابن عاشور: ۸؍۱۲۵)\nآیت کریمہ میں سرداروں اور ان کے پیروکاروں کے بیچ ہونے والی بحث وتکرار کا ذکر کیا گیا ہے ۔ اس بیان اور حکایت سے کیا سبق ملتا ہے؟\nقَالَ لِكُلّٖ ضِعۡفٞ وَلَٰكِن لَّا تَعۡلَمُونَ ٣٨\nمطلب یہ ہے کہ جہنم میں بحث وتکرار کرنے والے دونوں گروہوں میں سے کسی کو بھی یہ معلوم نہیں ہوگا کہ دوسرے گروہ کا عذاب کس درجہ کا ہے اور ان کی حالت کتنی ابتر اور سنگین ہے ۔کیونکہ کسی جہنمی کو اگر یہ معلوم ہوجائے کہ دوسرے کا عذاب اس کے اپنے عذاب سے بڑھ کر ہے تو یہ چیز اس کے لئے ایک طرح کی تسلی ہوگی۔ (القرطبی: ۹؍۲۲۲)\nاللہ تعالیٰ اہل جہنم سے ایک دوسرے کے عذاب کو چھپاکر (مخفی) کیوں رکھے گا؟\nإِنَّ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَٰبُ ٱلسَّمَآءِ وَلَا يَدۡخُلُونَ ٱلۡجَنَّةَ حَتَّىٰ يَلِجَ ٱلۡجَمَلُ فِي سَمِّ ٱلۡخِيَاطِۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُجۡرِمِينَ ٤٠\nآیت کے مضمون ومعنیٰ کا مخالف مفہوم یہ ہے کہ مومنوں کی روحیں جو اللہ کے حکم کی فرمانبردار وتابعدار ہوتی ہیں ،اس کی آیتوں کی تصدیق کرنے والی ہیں،ان کے لئے آسمان کے دروازے کھول دئے جائیں گے، یہاں تک کہ یہ روحیں اوپر چڑھتی جائیں گی، اور عالمِ بالامیں اس مقام اور درجے تک پہنچیں گی جس درجے تک اللہ چاہیگا، اور اپنے مالک کی نزدیکی اور اس کی رضا وخوشنودی کی سعادت پاکر لطف اندوز ہوں گی۔ (السعدی: ۲۸۸)\nاس آگاہی اور خبر سے کہ کافروں کی روحوں کے لئے آسمان کے دروازے بند ہوتے ہیں ،آپ کیا فائدہ بیان کریں گے؟\nلَهُم مِّن جَهَنَّمَ مِهَادٞ وَمِن فَوۡقِهِمۡ غَوَاشٖۚ وَكَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ ٤١\n(لَهُم مِّن جَهَنَّمَ مِهَادٞ) ان کے لئے جہنم کی آگ بچھونا ہوگا۔ (مِهَادٞ) سے مراد فراش یعنی بستر ،بچھونا۔ (وَمِن فَوۡقِهِمۡ غَوَاشٖۚ) اور ان کا اوڑھنا بھی اسی جہنم کی آگ کا ہوگا۔(غَوَاشٖۚ)یہ غَاشِيَۃٌ کی جمع ہے ،اس سے مراد لحاف یا اوڑھنے کی چادر ہے ۔ یعنی وہ چیز جو ان پر چھائی ہوئی ہوگی اور انہیں ڈھانپے ہوئے ہوگی۔چنانچہ آیت کا مطلب یہ ہوا کہ جہنم کی آگ انہیں ہر طرف سے گھیرے رہے گی۔(البغوی: ۲؍۱۰۳)\nآدمی جس طرح دنیا میں حرام طریقے سے حاصل کی ہوئی نعمتیں استعمال کرکے اپنے پورے جسم کو لذت اور فائدہ دیتا ہے ،اسی طرح قیامت کے روز عذاب بھی اس کے پورے جسم کے لئے عام ہوگا۔ اسے واضح کیجئے۔\nوَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَآ\n(وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ) اور جو لوگ ایمان لائے اور نیک اعمال کئے۔ یعنی :ان کے دلوں نے ایمان قبول کیا اور اعضاء وجوارح نے اچھے اعمال کئے۔برعکس ان لوگوں کے جنہوں نے اللہ کی آیتوں کا انکار اور کفر کیا، اور ان سے گھمنڈ کرتے ہوئے اعراض کیا۔ساتھ ہی یہاں اللہ تعالیٰ اس حقیقت سے آگاہ فرمارہا ہے کہ ایمان لانا اور اس پر عمل کرنا آسان ہے۔ اسی لئے اس نے فرمایا: (لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَآ) ہم ہر شخص کو اتنا ہی پابند بناتے ہیں جتنی اس کی طاقت ہو ۔ (ابن کثیر: ۲؍ ۲۰۵)\nایمان اور ہدایت کی راہ میں رکاوٹ بننے والی چیز یہ نہیں ہے کہ یہ دونوں مشکل اور پرمشقت ہیں ۔ آیت کی مدد سے اس بات کی وضاحت کیجئے.\nوَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلّٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُۖ\nاللہ تعالیٰ فرماتا ہے کہ: ہم نے یہ جن اہل ایمان کے اوصاف بیان کئے ہیں اور بتایا ہے کہ یہ جنتی لوگ ہیں،دنیا میں ان کے اندر ایک دوسرے کے خلاف جو کینہ تھا ،جو رنجش اور دشمنی تھی ،وہ سب ہم ان کے سینوں سے ختم کردیں گے۔ اب جب وہ جنت میں جائیں گے تو ان کی یہ تصویر ہوگی کہ بھائی بھائی بن کرایک دوسرے کے سامنے تختوں پر بیٹھے ہوں گے۔اللہ نے اگر کسی جنتی کو کسی خاص نعمت سے نوازا ہوگا، اور اپنی مہربانی اور کرم سے اسے دوسرے پر فضیلت عطا کی ہوگی تو ایسی کسی بھی چیز پر کوئی جنتی دوسرے کے لئے اپنے دل میں حسد نہیں رکھے گا ۔ ان کے نیچے نہریں بہہ رہی ہوں گی۔ (الطبری: ۱۲؍۴۳۷)\n“کینہ اور حسد کوچھوڑدینے میں ہی انسان کی سعادت وبھلائی ہے ”۔آیت کی روشنی میں اس بات کی وضاحت کریں.\nوَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ\nجو شخص نیکیاں کرتا ہے تو جس وقت وہ عمل کررہا ہوتا ہے،اس وقت اس کااچھا کام کرنا بذات خود اللہ کے فضل واحسان کی وجہ سے ہوتا ہے کہ اس نے بندے پر ہدایت اور ایمان کی توفیق دے کر اپنا فضل وکرم کیا ۔لہذا اس کے فضل واحسان کی بدولت ہی وہ بھلے کام کرنے والا بنا۔ اس بات کو اہل جنت ان الفاظ میں بیان کریں گے: (ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ ) تعریف اور شکر تو اس اللہ کے لئے ہے جس نے ہمیں یہ راہ دکھائی، اگر اللہ ہمیں یہ راہ نہ دکھاتا تو ہم کبھی یہ راہ نہ پاتے اور یہاں نہ پہنچتے۔ (ابن تیمیہ: ۳؍۱۶۲)\nبھلے کام کرنا یہ اللہ ہی کا احسان ہے ۔ آیت کریمہ کی روشنی میں اس حقیقت کو بیان کیجئے.\nwords\nادَّارَكُواوہ اس سے جا ملے.\nيَلِجَوہ داخل ہوتا ہے.\nسَمِّ الخِيَاطِسوئی کا سوراخ.\nغَوَاشٍوہ ڈھکن جو انہیں ڈھانک لے."],[156,"§الأعراف\ndeeds\nجنتیوں اورجہنمیوں کی صفات پر لکھی گئی کوئی کتاب پڑھئے.\nپیاسے کو پانی پلائیے، اوراس کو اپنی عادت بنالیجئے۔امید ہے کہ اللہ آپ کو اس کی وجہ کی سے آخرت میں فائدہ پہنچائیگا.\nایسے شرعی امور کی تعیین کیجئے جن کی بابت آپ کو احساس ہو کہ آپ نے سنجیدگی سے ان کی ادائیگی نہیں کی ہے، چنانچہ اب اللہ کی رضا کے لئے اپنی روش بدلنے کی کوشش کیجئے.\nguid\nکافروں کی صفتوں میں سے ایک یہ بھی ہے کہ وہ اللہ کے دین میں ناجائز تاویلوں اور تبدیلیوں کے ذریعہ شک وشبہ پیدا کرنے کی کوشش کرتے ہیں، معاشرے کو دین سے دور رکھنا چاہتے ہیں ،اچھائیوں اور خوبیوں کو ختم کردینا چاہتے ہیں،لوگوں کواپنے دین کے تعلق سے شک وشبہ میں مبتلا کردینا چاہتے ہیں، اورکافروں کو باعزت بنانا چاہتے ہیں.\nقیامت کے دن آپ کے مال ودولت کی کثرت یا پیروکاروں کی بہتات آپ کے کسی کام نہ آئیگی،نہ ہی رشتے دار واعزہ کی بھیڑ کچھ فائدہ دیگی، اور نہ ہی آپ کا مقام و مرتبہ یا حکومت آپ کے کچھ کام آسکے گی۔ صرف آپ کا عمل ہی آپ کے کام آئیگا.\nکسی کو بھی اس کی محتاجگی یا دنیا وی طور پر کمزور ہونے کے سبب حقیر نہ جانئے.\nrefl\nوَنَادَىٰٓ أَصۡحَٰبُ ٱلۡجَنَّةِ أَصۡحَٰبَ ٱلنَّارِ أَن قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقّٗا فَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقّٗاۖ قَالُواْ نَعَمۡۚ فَأَذَّنَ مُؤَذِّنُۢ بَيۡنَهُمۡ أَن لَّعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ ٤٤\nجنت والوں کا جہنم والوں کو یہ پکارنا دراصل جہنم والوں کے لئے جھڑکی ہوگی،ڈانٹ ڈپٹ اور سرزنش ہوگی۔ساتھ ہی ان کے رنج اور تکلیف کو بڑھا دینے والی ہوگی۔ (ابن عطیہ: ۲؍ ۴۰۲)\nجنت والوں کی طرف سے جہنم والوں کو پکارنے کا کیا فائدہ ہوگا؟\nوَهُم بِٱلۡأٓخِرَةِ كَٰفِرُونَ ٤٥\nیہی وہ چیز ہے جو سیدھے راستے سے ان کے پھر جانے کی وجہ بنی۔نیزثواب کی امید نہ رکھناہی ان کے نفسانی شہوتوں اورخواہشات پر ٹوٹے پڑے رہنے کی وجہ بنی۔ (السعدی: ۲۹۰)\nموت کے بعد دوبارہ اٹھائے جانے اور آخرت پر ایمان ویقین رکھنے کا کیا اثر ہوتا ہے؟\nوَبَيۡنَهُمَا حِجَابٞۚ وَعَلَى ٱلۡأَعۡرَافِ رِجَالٞ يَعۡرِفُونَ كُلَّۢا بِسِيمَىٰهُمۡۚ وَنَادَوۡاْ أَصۡحَٰبَ ٱلۡجَنَّةِ أَن سَلَٰمٌ عَلَيۡكُمۡۚ لَمۡ يَدۡخُلُوهَا وَهُمۡ يَطۡمَعُونَ ٤٦\nاہلِ جنت اور اہلِ جہنم کے درمیان ایک آڑ یعنی دیوارہوگی۔اسی کو “اَعراف” کہا جاتا ہے ۔ یہ دیوار نہ جنت کا حصہ ہوگی اور نہ جہنم کا ۔ یہ دیوار اتنی اونچی ہوگی کہ اس پر جو کوئی رہے گا وہ دونوں ٹھکانوں میں جھانک سکے گا اور دونوں فریق یعنی اہلِ جنت اور اہلِ جہنم کے حالات دیکھ پائے گا۔ چنانچہ اس دیوار پر کچھ لوگ ہوں گے جو جنت اور جہنم والوں میں سے ہر ایک کو پہچان لیں گے۔ (بِسِيمَىٰهُمۡۚ) یعنی ان نشانیوں اور علامتوں کے ذریعہ جو جنتی اور جہنمی افراد کی پہچان ہیں، اور جن کے ذریعہ وہ دوسروں سے الگ اور ممتاز ہوتے ہیں۔سو جب وہ اہلِ جنت کی طرف نظر ڈالیں گے تو انہیں پکار کر کہیں گے: (أَن سَلَٰمٌ عَلَيۡكُمۡۚ) کہ تم پر سلامتی ہو۔ اور تحیّت وسلام کا نذرانہ پیش کریں گے، حالانکہ وہ خود اب تک جنت میں داخل نہیں ہوئے ہوں گے، لیکن اس میں داخلہ کی آس اور امید لگائے ہوں گے۔اور اللہ تعالیٰ ان کے دلوں میں یہ امید اور آرزویوں ہی نہیں جگائیگا، بلکہ اللہ ان کے دلوں میں اس لئے امید پیدا کریگا کہ وہ اپنے فضل وکرم کا معاملہ ان کے ساتھ کرنا چاہتاہے۔ (السعدی: ۲۹۰)\nاصحابِ اعراف(اعراف والوں)سے کیا مراد ہے؟\nوَنَادَىٰٓ أَصۡحَٰبُ ٱلۡأَعۡرَافِ رِجَالٗا يَعۡرِفُونَهُم بِسِيمَىٰهُمۡ قَالُواْ مَآ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ ٤٨\n(وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡأَعۡرَافِ رِجَالٗا) اور اہلِ اعراف کچھ لوگوں کو آواز دیں گے۔یہ وہ جہنمی ہوں گے جودنیا میں بڑے اثر ورسوخ والے تھے ۔ (يَعۡرِفُونَهُم بِسِيمَىٰهُمۡ قَالُواْ مَآ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ) (اہلِ اعراف ) انہیں ان کی خاص نشانیوں سے پہچان لیں گے اور کہیں گے تمہارا جمع جمع کر رکھنا تمہارے کام نہیں آیایعنی: دنیا کے مال واسباب اور آل اولاد۔ (وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ) اور وہ چیزیں جن کے بل بوتے پر تم ایمان لانے سے اکڑتے اور تکبر کرتے تھے اور شیخی میں حق قبول نہیں کرتے تھے ۔ کلبی رحمہ اللہ کہتے ہیں: وہ دیوار اعراف پر ہوں گے اور وہیں سے پکاریں گے :اے ولید بن مغیرہ!اے ابوجہل بن ہشام ! او فلاں! وہ انہیں جہنم میں مبتلائے عذاب دیکھ رہے ہوں گے۔پھر وہ اپنی نگاہوں کو جنت کی طرف پھیریں گے تو اس میں دنیا کے فقراء ومحتاجین اور کمزور لوگوں کو دیکھیں گے جن کا ان بڑے لوگوں کی طرف سے مذاق اڑایا جاتا تھا، جیسے حضراتِ سلمان،صہیب،خبّاب اور بلال رضی اللہ عنہم ۔ (البغوی: ۲؍۱۰۶)\nدنیا کے پیمانے آخرت کے پیمانوں سے الگ ہیں ۔ آیت کے تناظر میں اس بات کی کچھ وضاحت کیجئے.\nأَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمۡتُمۡ لَا يَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍۚ\nیہ اصحابِ اعراف کے اس کلام کا حصہ ہے جسے وہ اہلِ جہنم سے خطاب کرکے کہیں گے۔یہاں (هَٰٓؤُلَآءِ) (یہ لوگ) کا اشارہ اہلِ جنت کی طرف ہے ۔ اس بات کا پس منظر یہ ہے کہ یہ کافر لوگ دنیا میں قسمیں کھاکھاکر کہتے تھے کہ اللہ تعالیٰ مومنوں پر رحم نہیں کریگا،اپنی رحمت سے محروم رکھے گا،اور ان کی کوئی پرواہ نہیں کریگا،مگر یہاں جو منظر اور نتیجہ سامنے ہوگا وہ ان کی اس بات کے بالکل خلاف ہوگا۔ (ابن جُزی: ۱؍ ۳۶۰)\nاس آیت سے جہنم میں جانے کے چند اسباب بیان کیجئے.\nوَنَادَىٰٓ أَصۡحَٰبُ ٱلنَّارِ أَصۡحَٰبَ ٱلۡجَنَّةِ أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوٓاْ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَٰفِرِينَ ٥٠\nیہ آیت اس بات کی دلیل ہے کہ پانی پلاناافضل ترین اعمال میں سے ہے۔ ابن عباس رضی اللہ عنہما سے پوچھا گیاکون سا صدقہ سب سے زیادہ فضیلت والا ہے؟ تو انہوں نے فرمایا: پانی،کیا تم نے اہلِ جہنم کو نہیں دیکھا کہ جب وہ اہل جنت سے فریاد ومدد چاہیں گے تو کہیں گے: (أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ) یعنی: ہم پر بھی تھوڑا سا پانی انڈیل دویا اللہ نے تمہیں جو رزق دیا ہے اسی میں سے کچھ گرادو۔ بعض تابعین کا قول ہے:جس کے گناہ زیادہ ہوجائیں اسے لوگوں کوپانی پلانا چاہئے ۔اور واقعہ ایسا ہی ہے کہ ایک شخص نے کتے کو پانی پلادیا تو اللہ نے اس کے گناہوں کو معاف کردیا،تو پھر اسے بخشش کیوں نہیں ملے گی جو کسی مومن وموحد (ایمان وتوحید والے )انسان کو پانی پلائے اور سیراب کرکے اس کی زندگی اور تازگی کا ذریعہ بنے۔ (القرطبی:۹؍۲۳۳)\nکون سی چیز پانی پلانے کی فضیلت پر دلالت کرتی ہے؟بیان کیجئے.\nوَنَادَىٰٓ أَصۡحَٰبُ ٱلنَّارِ أَصۡحَٰبَ ٱلۡجَنَّةِ أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوٓاْ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَٰفِرِينَ ٥٠\nاس بات چیت کے اندر جوچیز کافروں کو سب سے زیادہ بری لگے گی وہ یہ ہوگی کہ وہ یعنی جنتی اور جہنمی ایک دوسرے کو دیکھ رہے ہوں گے ،ایک دوسرے کے حالات کا مشاہدہ کررہے ہوں گے ۔ تو یہ چیز ان کے اندر ذلت ورسوائی کا احساس بڑھا دیگی ،اور ان کے دل کو زیادہ چوٹ پہنچائیگی۔ (ابن عطیہ: ۲؍ ۴۰۶)\nجہنم میں ایک طرف جہاں جسمانی عذاب ہوگا ،وہیں دوسری طرف معنوی عذاب بھی ہوگا۔ آیت کے معنی ومفہوم کے تحت اس بات کی وضاحت کیجئے.\nwords\nحِجَابٌپردہ / رکاوٹ / آڑ.\nبِسِيمَاهُمان کی نشانیوں سے.\nتِلقَاءَجھت.\nأَصحَابُ الأَعرَافِجن کی نیکیاں اور برائیاں برابر ہوں."],[157,"§الأعراف\ndeeds\nعاجزی کے ساتھ اللہ تعالیٰ سے اس طرح دعائیں مانگئے کہ کسی کوخبر نہ ہونے پائے.\nراستہ چلتے ہوئے تکلیف دہ چیزیں ہٹاتے رہئے۔اور اگر کوئی چیز بگڑی ہوئی نظر آئے جس کی درستی ممکن ہو تو امکان بھر اس کی اصلاح اور درستی کی کوشش کیجئے.\nکچھ ایسے وسائل متعین کرکے ایسی سوچ وفکر بنا ئیے کہ آپ لوگوں کے ساتھ احسان اور حسن سلوک کو اپنی عادت بناسکیں، اور اللہ تعالیٰ سے دعا مانگئے کہ وہ آپ کو اہلِ احسان میں سے بنادے.\nguid\nاللہ کی کتاب قرآن کریم میں ہدایت ،رحمت اور علم سبھی کچھ ہے.\nموت کے آثار اور عذاب کو دیکھ لینے کے بعد ایمان لانابے فائدہ ہے، جس طرح قیامت کے دن ایمان لانے کا کوئی فائدہ نہ ہوگا.\nاگر اللہ کی رحمت کے خواہش مند ہوں تو ہر ایک کے ساتھ حسن سلوک کرنے والوں میں سے بن جائیے.\nrefl\nوَلَقَدۡ جِئۡنَٰهُم بِكِتَٰبٖ فَصَّلۡنَٰهُ عَلَىٰ عِلۡمٍ\nعَلٰى عِلْمٍ) علم کی بناپر۔ یعنی کتاب میں ہر چیز کی تفصیل اللہ کے اس علم کی بناپر ہے جو ہر زمانے اور ہر علاقے میں بندوں کے تمام حالات کو پوری طرح سے گھیرے ہوئے ہے ۔ وہ خوب جانتا ہے کہ بندوں کے لئے کیا بہتر ہے اور کیا بہتر نہیں ہے۔ لہذا اللہ کا ہر چیز کو صاف صاف تفصیل کے ساتھ بیان کرنا کسی ایسی ذات کی طرح بیان کرنا نہیں ہے جو معاملات اور چیزوں کاپورا علم نہیں رکھتی،بلکہ بعض حالات اور حقائق سے وہ ناواقف ہوتی ہے، اور اپنی کم علمی کی بناپر نامناسب فیصلہ لے لیتی ہے ۔اللہ کا معاملہ ایسا قطعی نہیں ہے، بلکہ اس کی تفصیل یعنی ہر فیصلہ اور ہر حکم اس ہستی کی تفصیل ہے جس کے علم نے ہر چیز کو گھیر رکھا ہے، اور اس کی رحمت ہر چیز پر چھائی ہوئی ہے ۔ (السعدی: ۲۹۱)\nآپ اس شخص کی تردید کیسے کریں گے جو یہ دعویٰ کرتا ہے کہ شریعت اسلامیہ موجودہ زمانے کے لائق نہیں ہے ؟\nٱدۡعُواْ رَبَّكُمۡ تَضَرُّعٗا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ٥٥\nشریعت کا یہ طے شدہ ضابطہ ہے کہ جو نیک اعمال فرض نہیں ہیں انہیں اعلانیہ طورپرکرنے کے مقابلے میں چھپاکر انجام دینے میں ثواب زیادہ ہے ۔ حسن بن ابو الحسن رحمہ اللہ کہتے ہیں :“ہم نے ایسے لوگوں کو پایا ہے کہ وہ روئے زمین پر کوئی بھی نیک عمل کرتے ،اگرچھپاکر کرنا ان کے بس میں ہوتا تو وہ کبھی بھی اسے ظاہر نہیں کرتے ۔یقیناًوہ مسلمان ایسے تھے کہ دعا کرنے میں خوب محنت کرتے تھے ،لیکن ان کی آواز سنائی نہیں دیتی تھی ۔یہ دعائیں تو بس ان کے اور ان کے رب کے بیچ سرگوشی ہوتی تھیں”۔ (القرطبی: ۹؍۲۴۴۔۲۴۵)\nسرّی (چھپا کر) عبادت کرنا افضل وبہتر ہے یا علانیہ اور دکھاکر؟\nٱدۡعُواْ رَبَّكُمۡ تَضَرُّعٗا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ٥٥\nاللہ تعالیٰ ارشاد فرمارہا ہے کہ : اے لوگو! صرف اپنے اکیلے رب کو پکارو۔ پس !اس کے علاوہ جن معبودوں اور بتوں کو تم پکارتے ہو انہیں چھوڑکر ،دعا کو صرف اسی رب کے لئے خالص کرو۔ کسی اور سے مانگ کر اپنی دعا میں ملاوٹ اور شرک نہ کرو۔ (تَضَرُّعًا) گڑگڑاتے ہوئے،آہ وزاری کرتے ہوئے ۔ فرماتا ہے : عاجزی سے ،نیاز مندی کے ساتھ اور اس کی فرمانبرداری میں جھک کر اسے پکارو۔ (وَ خُفْيَةً) اور چپکے چپکے بھی ۔ آوازبہت اونچی نہ ہو، اورنہ ہی کسی طرح کی ریاکاری ہو۔نیز اہل نفاق اور اللہ اور اس کے رسول صلی اللہ علیہ وسلم کو دھوکا دینے والوں کے عمل کی طرح یہ بھی نہیں ہونا چاہئے کہ دعاکرتے ہوئے تمہارے دلوں میں اللہ کی وحدانیت اور ربوبیت کا یقین نہ ہو۔ (الطبری: ۱۲؍ ۴۸۵)\nبندۂ مومن کو دعا کی حالت میں کون سی صفات اکٹھا رکھنا چاہئے؟\nوَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا\nجو شخص مخلوق کے حالات پر غور وفکرکریگا ،وہ اس حقیقت کو جان لے گاکہ دنیا میں جو بھی بھلائی اور اچھائی ہے اس کا سبب اللہ کی توحید ،اس کی عبادت اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت ہے، اور دنیا کی ہر برائی ،فتنہ وفساد ،مصیبت وبلاء ،قحط وخشک سالی ،دشمن کا مسلط ہونا ،اور دیگر جتنی خرابیاں ہیں سب کا سبب رسول اللہ صلی اللہ علیہ وسلم کی مخالفت، اور لوگوں کو اللہ کے علاوہ اوروں کی طرف بلانا،اورشرک کی طرف بلانا ہے ۔ (ابن تیمیہ: ۳؍۱۷۰)\nدنیا کی ہر اچھائی کا سبب اور ہربرائی کی جڑ کیا ہے؟\nوَٱدۡعُوهُ خَوۡفٗا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ ٥٦\nیہ بات اچھی طرح جان لیجئے کہ خوف کے تین درجے ہیں: ۱. پہلا درجہ: خوف ایسا کمزور ہو جو دل میں کھٹکتا تو ہو لیکن آدمی کی اندرونی اوربیرونی حالت پر اثر انداز نہ ہوتا ہو۔ تو اس خوف کاہونا نہ ہونے کے برابر ہے۔ ۲. دوسرا درجہ: خوف مضبوط ہو ،اتنا مضبوط کہ بندے کو غفلت سے بیدار کردے، اور ثابت قدمی پر ابھارے۔ ۳. اور تیسرا درجہ : خوف اس قدر شدید ہو کہ بندے کو ناامیدی اور مایوسی کی حد تک پہنچادے اور یہ خوف جائز نہیں ہے ۔ یقیناًمیانہ روی یعنی بیچ کا راستہ ہر معاملے میں سب سے بہتر ہے ۔ اسی طرح ڈر،خوف میں لوگوں کے بھی تین مرتبے ہیں: ۱۔عام لوگ گناہوں سے ڈرتے ہیں ۔ ۲۔ خاص لوگ برے خاتمہ سے ڈرتے ہیں۔ ۳۔ انتہائی خاص لوگ سابقہ (یعنی نیکیوں میں دوسرے نمبر پر ہونے)سے ڈرتے ہیں۔وہ ڈرتے ہیں کہ اعمالِ خیر میں پیچھے نہ رہ جائیں ،نیک کاموں میں پچھڑ نہ جائیں ۔کیونکہ حسنِ خاتمہ اسی پر منحصر ہے ۔(ابن جُزی: ۱؍ ۳۶۰)\nاس آیت میں ذکر کیا گیا خوف ‘کون سا خوف ہے جس کے ذریعہ اللہ کی عبادت کی جاتی ہے؟\nوَٱدۡعُوهُ خَوۡفٗا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ ٥٦\nرَجاء: یعنی امید کے بھی تین درجات ہیں: أ۔ پہلا درجہ یہ ہے کہ: اللہ کی رحمت کی آس و آرزو ہو۔لیکن یہ آس اور امید یوں ہی خالی خولی نہ ہو۔ بلکہ امید کے اسباب وذرائع کے ساتھ ہو۔ اور اس کے اسباب ہیں: نیکی اور فرمانبرداری کے کاموں کو کرنا، اور برائی ونافرمانی کے کاموں کو چھوڑدینا، تو یہ قابلِ تعریف اور اچھی امید ہے ۔ ب۔ دوسرا درجہ: کوتاہیاں اور نافرمانیاں کرتے ہوئے امید رکھنا۔ ایسی امید رکھنا خود کو دھوکے میں رکھنا ہے ۔ ج۔ تیسرا درجہ یہ ہے کہ: امید مضبوط ہو ۔اتنی مضبوط کہ حدِ اعتدال سے آگے بڑھ جائے ۔یہاں تک کہ اللہ کے عذاب سے بے خوفی تک پہنچ جائے ۔ تو اس درجے کی امید حرام ہے ۔ نیز لوگ امید ورجاء کے معاملے میں بھی تین مرتبے کے ہوتے ہیں: ۱۔ عوام کا مقام ہے:اللہ کے ثواب کی امید رکھنا۔ ۲۔ خاص لوگوں کا مقام ہے :اللہ کی رضا وخوشنودی کا امیدوار ہونا۔ ۳۔ انتہائی خاص لوگوں کا مقام ہے:اللہ سے ملاقات کی امید رکھنا ،جس میں اللہ کی محبت اور اس سے ملنے کا شوق شامل ہو۔ (ابن جُزی: ۱؍ ۳۶۰)\nاس آیت میں ذکر کردہ امید کون سی امید ہے جس کے ساتھ اللہ کی عبادت کرنی چاہئے؟\nإِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ ٥٦\nاللہ کی رحمت سے قریب ہونے میں اہلِ احسان کو خاص کیا گیا ہے کہ خصوصیت کے ساتھ وہی لوگ اللہ کی رحمت سے قریب ہیں جو احسان کرنے والے ہیں۔ کیونکہ یہ اللہ عزوجل کا احسان وکرم ہے جو بذات خود ارحم الراحمین ہے، اور اللہ تبارک وتعالیٰ کا احسان اہلِ احسان کے لئے ہی ہوتا ہے، اس لئے کہ جزاء عمل کی جنس سے ہوتی ہے، یعنی جس قسم کا عمل ہوتا ہے اسی قسم کا بدلہ ملتا ہے ۔غرض بندے اپنے اعمال میں جتنا احسان کرتے جاتے ہیں بدلے میں اللہ تعالیٰ ان پر اپنی رحمت کے ساتھ اتنا ہی احسان وکرم کرتا جاتا ہے ۔ (ابن تیمیہ: ۱۵؍۲۷)\nاللہ کی رحمت سے قربت ونزدیکی میں اہلِ احسان کو خاص کیوں کیا گیا ہے؟\nwords\nاستَوَىبلند ہوا؛ اوپر چڑھا.\nحَثِيثًاسریع /دائمی.\nوَخُفيَةًچپکے سے.\nأَقَلَّتاس نے اٹھایا(حمل).\nثِقَالًاپانی سے بھرپور.\nلِبَلَدٍخشک سالی کاشکار علاقہ."],[158,"§الأعراف\ndeeds\nاپنی زبان،دل اور عمل سے اللہ تعالیٰ کا شکر ادا کیجئے، اور بکثرت شکر ادا کرنے والے بنئے، کیونکہ نعمتوں پر شکر گذاری علم،فہم وفراست اور ایمان میں زیادتی کے اسباب میں سے ہے.\nاللہ تعالیٰ سے دعائیں مانگئے کہ کمزور ومظلوم توحیدپرستوں کو نجات عطافرمائے، اور سرکش ،حدسے تجاوزکرنے والے ظالموں کو ہلاک کرے.\nتوحید کے باب میں آپ کو جن مسائل کی ضرورت ہے ،ان کا علم حاصل کیجئے، اور اپنے آس پاس والوں کو بھی ان سے واقف کرائیے.\nguid\nتوحید کے باب میں تمام انبیاء کی دعوت یکساں ہے۔چنانچہ آپ اس عظیم بنیاد کو سیکھنے،سکھانے اور اسے عملی طور پر نافذ کرنے میں پوری محنت کیجئے.\nمال ومنصب اور اثرورسوخ والوں میں سے گمراہ لوگ ہی دعوتِ حق کو جھٹلانے میں پیش پیش رہتے ہیں، اس وجہ سے کہ وہ ان کی خواہشات کے مخالف ہوتی ہے.\nداعی اگر ان دوصفات(سچی خیر خواہی اور علم) سے متصف ہوجائے تو یقیناًاس کی دعوت میں برکت بھی ہوتی ہے اور اسے قبولیت بھی ملتی ہے ۔ چنانچہ آپ یہ دونوں صفات اپنے اندر پیدا کرنے کے لئے خوب جتن کیجئے.\nrefl\nوَٱلۡبَلَدُ ٱلطَّيِّبُ يَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ وَٱلَّذِي خَبُثَ لَا يَخۡرُجُ إِلَّا نَكِدٗاۚ كَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَشۡكُرُونَ ٥٨\nوحی الٰہی کے اترنے اور آنے کے وقت دلوں کی جو حالت ہوتی ہے ،یہ اسی کی مثال ہے کہ جب پاکیزہ اور صاف ستھرے دلوں کے پاس وحی آتی ہے تو وہ اسے قبول کرتے ہیں ،سیکھتے ،سمجھتے ہیں، اور پھر اپنی اصل یعنی طبیعت وفطرت کی طہارت وپاکیزگی کے مطابق اور اپنے بنیادی مادے کی خوبی کے مطابق نشونما پاتے ہیں ۔ رہے وہ دل جن میں گندگی اورخباثت ہوتو جب ایسے دلوں کے پاس وحی آتی ہے تو وہ قبول کرنے والی جگہ اور قابل زمین نہیں پاتی، بلکہ وہ ایسے دلوں کو غافل وبے پروا ہ پاتی ہے ،جو یا تو اعراض کرنے والے ہوتے ہیں یامخالفانہ روش والے ہوتے ہیں، تو دلوں کی اس صورت حال پر وحی اُس بارش کی طرح ہوتی ہے جو کیچڑ والی زمین پر ، ریتیلی زمین اور سخت پتھروں والی زمین پر برس کر بہہ جاتی ہے مگر ان زمینوں پر اس کا کچھ بھی اثر باقی نہیں رہتا ۔ (السعدی: ۲۹۲)\nوحی کو قبول کرنے کے سلسلے میں دلوں کی کتنی قسمیں ہیں؟\nقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي ضَلَٰلٖ مُّبِينٖ ٦٠\n(قَالَ الْمَلَاُ مِنْ قَوْمِهٖ) ان کی قوم کے بااثر لوگوں نے کہا: یعنی:قوم کے شرفاء،سرداروں،پیشواؤں اور رسوخ والے لوگوں نے کہا: (اِنَّا لَنَرٰىكَ فِيْ ضَلٰلٍ مُّبِيْنٍ) ہم تو یہ دیکھ رہے ہیں کہ تم صریح گمراہی میں پڑ گئے ہو۔ یعنی: اس بات میں کہ تم ہمیں بتوں کو چھوڑ دینے کی دعوت دے رہو جن کی عبادت اور تعلق پر ہم نے اپنے باپ دادا کو پایا تھا۔ بدکار وگناہ گار لوگوں کا یہی حال ہوتا ہے، وہ نیک اور اچھے لوگوں کوگمراہ سمجھتے ہیں۔ جیسا کہ اللہ تعالیٰ نے نقل فرمایاہے : (وَ اِذَا رَاَوْهُمْ قَالُوْۤا اِنَّ هٰۤؤُلَآءِ لَضَآلُّوْنَۙ۰۰۳۲) (سورۂ مطفِّفین: ۳۲)اور جب مجرمین انہیں یعنی مومنین کو دیکھتے تو کہتے یقیناًیہ لوگ بھٹکے ہوئے گمراہ ہیں۔ (وَ قَالَ الَّذِيْنَ كَفَرُوْا لِلَّذِيْنَ اٰمَنُوْا لَوْ كَانَ خَيْرًا مَّا سَبَقُوْنَاۤ اِلَيْهِ) (سورۂ احقاف:۱۱) جن لوگوں نے کفر کیا انہوں نے ایمان والوں کے بارے میں کہا کہ اگر یہ (دین) بہتر ہوتا تو یہ لوگ اس کی طرف ہم سے پہل نہیں کرپاتے ،اور اسے ماننے میں ہم سے آگے نہیں بڑھ پاتے۔ (ابن کثیر: ۲؍ ۲۱۴)\nآیت کے تناظر میں نیک لوگوں کو پیش آنے والی بعض آزمائشوں کا ذکر کیجئے.\nقَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ٦١\nرسول کی یہی شان ہوتی ہے : وہ تبلیغ کرنے والا،فصیح،صاف صاف بیان کرنے والا، اور اللہ کو جاننے والا ہوتا ہے ۔ (ابن کثیر: ۲؍ ۲۱۴)\nاللہ کی طرف دعوت دینے والے کو کن صفات سے متصف ہونا چاہئے؟\nقَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ٦١ أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ٦٢\nرسول کی یہی شان ہوتی ہے : وہ تبلیغ کرنے والا،فصیح،صاف صاف بیان کرنے والا، اور اللہ کو جاننے والا ہوتا ہے ۔ (ابن کثیر: ۲؍ ۲۱۴)\nاللہ کی طرف دعوت دینے والے کو کن صفات سے متصف ہونا چاہئے؟\nأُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ٦٢\nیعنی: میری ذمہ داری ہے کہ اللہ کی توحید اور اس کی حکم کردہ اور منع کردہ چیزوں (اوامر ونواہی) کو وضاحت کے ساتھ تم تک پہنچادوں، اور یہ کام تمہارے ساتھ خیر خواہی اور تم پر شفقت ونرمی کے انداز میں کروں۔ (وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ) اور میں اللہ کی طرف سے اس بات کا علم رکھتا ہوں جو تمہیں معلوم نہیں ہے ۔ اس حقیقت کی بنیاد پر جو بات طے ہوتی ہے وہ یہ کہ تم میری اطاعت کرو، اور اگر تم سوجھ بوجھ رکھتے ہو تو میرے حکم کی پیروی کرو۔ (السعدی: ۲۹۳)\nجب رسول اللہ کی طرف سے وہ باتیں جانتے تھے جسے لوگ نہیں جانتے ۔تو یہ سچائی لوگوں پر کیا چیز واجب کرتی ہے ؟\nفَكَذَّبُوهُ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمًا عَمِينَ ٦٤\nغرق کرنے سے پہلے بچانے کا ذکر کیا گیا ہے ۔جس کا مقصد مومنوں کو نجات دینے کا خاص اہتمام کرنا ہے، اور اس کی خصوصی اہمیت اجاگر کرنا ہے ۔ ساتھ ہی ایمان والے سامعین کو خوشی کی بات سنانے میں جلدی اور پہل کی جائے اور انہیں معلوم ہوجائے کہ :اللہ جب مشرکین کو ہلاک کرتا ہے تو اس کی عادت اور دستور یہ ہے کہ رسول اور مومنوں کو بچالیتا ہے ۔ (ابن عاشور: ۸؍۱۹۷)\nآیت کریمہ میں کافروں کو غرق کرنے سے پہلے مومنوں کو نجات دینے کا ذکر کیوں کیا گیا ہے؟\nفَكَذَّبُوهُ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ\nبندوں کے بارے میں اللہ کی یہ سنت ہے دنیا میں بھی اور آخرت میں بھی کہ: ہر دوجگہ انجام متقیوں کے حق میں ہوتا ہے ۔غلبہ اور جیت بالآخر انہی کے حصے میں آتی ہے۔جس کی ایک مثال یہ ہے کہ اللہ نے نوح علیہ السلام کی قوم کے کافروں اور مشرکوں کو غرق کرکے مٹادیا، جبکہ حضرت نوح علیہ السلام اور ان کے رفقاء اور ایمان والے ساتھیوں کو بچالیا۔ (ابن کثیر: ۲؍ ۲۱۴)\nحضرت نوح علیہ السلام کے قصے میں پریشان حال مسلمانوں کے لئے ایک اہم سبق ہے ۔ وہ کیا ہے؟\nwords\nنَكِدًاتنگ / ردی.\nنُصَرِّفُہم اس میں تنوع پیدا کرتے ہیں.\nعَمِينَدل کے اندھے جو حق کو نہ دیکھ سکیں.\nسَفَاهَةٍعقلی پستی."],[159,"§الأعراف\ndeeds\nاگر آپ معاشرے میں کوئی برائی یا بگاڑ دیکھ رہے ہوں تو آج ہی اچھے اسلوب میں تبلیغ کا فریضہ ادا کیجئے.\nکچھ دیر کے لئے تنہابیٹھ کر ان نعمتوں اور بھلائیوں کو یاد کیجئے جن سے اللہ تعالیٰ نے آپ کو نوازا ہے.\nاللہ تعالیٰ سے دعائیں مانگئے کہ ہمارے زمانے کے مظلوم وبے بس مسلمانوں کو اپنی رحمت سے نجات عطا فرمائے، اوردشمنانِ دین کو اپنی قدرت سے ملیامیٹ کردے.\nguid\nمشرکین اپنے باطل کے صحیح ہونے پر باپ دادا کے عمل سے دلیل پکڑتے ہیں ۔گویا کہ یہ باطل پرستوں کاعام طریقہ رہا ہے، اور یہ قابل مذمت تقلید کی ہی ایک شکل ہے.\nدراصل یہ مشرکین کی جہالت ہے کہ وہ عذاب کے جلدی لانے کا مطالبہ کرتے ہیں، بلکہ از خود بھی اسے طلب کرتے ہیں.\nکوئی بھی حکم ،یا فیصلہ، یا بات جس پرقرآن وسنت کی دلیل نہ ہو ،وہ یقیناًباطل ہے.\nrefl\nأُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ ٦٨\nیہ وہ صفات ہیں جن سے اللہ کے رسول وپیغمبر متصف ہوتے ہیں: پیغام رسانی، خیر خواہی، اور امانت داری ۔ (ابن کثیر: ۲؍ ۲۱۵)\nوہ کون سی صفات ہیں جن سے ایک داعی کو اپنی دعوت کے کام میں آراستہ ہونا ضروری ہے ؟\nوَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ ٦٩\nحضرت ہود علیہ السلام نے اپنی قوم کو پہلے توحید کی دعوت دی ،پھر ان پر اللہ کی نعمتوں کی یاد دہانی کی طرف منتقل ہوئے ۔ جن کے بارے میں وہ انکار نہیں کرسکتے تھے، بلکہ اچھی طرح جانتے تھے کہ یہ نعمتیں صرف اللہ کی طرف سے ملی ہیں ،کیونکہ پیدا کرنا،اور حکم دینا دونوں صفتیں اسی اللہ کے لئے خاص ہیں کسی اور کے لئے نہیں ہیں۔اس یاد دہانی کا بنیادی مقصد انہیں اس نتیجہ تک پہنچانا تھا کہ وہ عبادت میں اللہ کو اکیلا جانیں ،توحید اختیار کریں۔ (ابن عاشور: ۸؍۲۰۴)\nتوحید کا حکم دینے کے فوری بعدنعمتوں کی یاد دہانی کیوں کرائی گئی؟\nوَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ ٦٩\nاس یاد دہانی میں نعمت کے تعلق سے صاف صاف بتانا اور دھمکی اور ڈراوے کی جانب اشارہ کرنا ہے کہ اللہ کے عذاب نے نوح علیہ السلام کی قوم کو شرک کرنے کی وجہ سے نیست ونابود اور ہلاک وبرباد کردیا ۔لہٰذا جواُن کی اس حرکت اورکرتوت میں ان کے نقشِ قدم پر چلے گاتو قریب ہے کہ اس پر بھی عذاب الٰہی نازل ہوجائے ۔ (ابن عاشور: ۸؍۲۰۵)\nآیت کے تناظر میں اس بات کو واضح کیجئے کہ کیاکسی پورے سماج اور معاشرے کو کلی طور پرعذاب دیا جانا ممکن ہے ؟\nوَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ\nاور اللہ نے تمہیں ہلاک ہونے والی قوموں کا جانشین بنایا ،جنہوں نے رسولوں کو جھٹلایا تھا۔ اسی کے پاداش میں اللہ نے انہیں صفحۂ ہستی سے مٹادیا اور تمہیں باقی رکھا۔ تاکہ وہ تمہیں دیکھے اور آزمائے کہ تم کیسا عمل کرتے ہو؟اور دیکھواس بات سے بچتے رہنا کہ تم بھی ان لوگوں کی طرح حق کو جھٹلانے پر اڑے اور ڈٹے رہو۔ ورنہ تمہارا بھی وہی انجام ہوگا جو ان کا انجام ہوا۔ (السعدی: ۲۹۴)\nحضرت ہود علیہ السلام نے اپنی قوم سے قوم نوح کا ذکر کیوں کیا؟\nقَالُوٓاْ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ٧٠\nاللہ ان کا برا کرے کہ انہوں نے سب سے بڑی واجب چیز اور سب سے زیادہ کامل چیز یعنی توحید کوایسے امورمیں شمار کیا جن کے ذریعہ ان کے باپ دادا کے رسم ورواج کا مقابلہ نہیں کیا جاسکتا،چنانچہ رسولوں کی دعوت یعنی اللہ وحدہ لاشریک کی توحید کے مقابل،حق سے بھٹکے ہوئے باپ دادا کے طورطریقے یعنی شرک اور بت پرستی کو ترجیح دی۔ اپنے نبی کو جھٹلایا، اور ان کی دعوت کو قبول کرنے سے انکار کردیا۔ اور یہاں تک جسارت کرڈالی کہ اپنے نبی سے کہا: (فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ) اگرتم سچے ہو تو وہ ۔عذاب۔ جس کی ہمیں دھمکی دے رہے ہو اسے لاکر دکھاؤ۔ (السعدی: ۲۹۴)\nجب قوم کی سوچ سمجھ اور رسم ورواج اللہ سبحانہ وتعالیٰ کی شریعت سے ٹکراتے ہوں تو ایسے میں ایک بندۂ مومن کا موقف اور طریقہ کیا ہوتا ہے؟\nقَالَ قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٞ وَغَضَبٌۖ أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٖ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٖۚ\n(قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٞ وَغَضَبٌۖ) یقیناًتمہارے رب کی طرف سے تم پر عذاب اور غضب واقع ہوچکا ہے ۔ یعنی عذاب کا واقع ہونا اٹل ہے ۔ اس لئے کہ عذاب کے اسباب فراہم ہوچکے ہیں اور ہلاکت کا وقت بھی آپہنچا ہے ۔ (أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٖ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم) کیا تم مجھ سے ایسے ناموں کے بارے میں جھگڑ رہے ہو جو تم نے اور تمہارے آباء واجداد نے -اپنے جی سے-رکھ لئے ہیں؟ یعنی تم کس طرح ایسی چیزوں کے تعلق سے مجھ سے جھگڑا کررہے ہو جن کی کوئی حقیقت ہی نہیں ہے ؟ اور ایسے بتوں کے بارے میں کیسے تکرار کر رہے ہوجنہیں تم لوگوں نے-اپنی طرف سے -معبود اور الٰہ کا نام دے دیا ہے ؟حالانکہ ان کے اندر الوہیت یعنی معبود ہونے کی کوئی بھی بات اور کچھ بھی خصوصیت نہیں ،ذرہ برابر بھی نہیں ۔ (السعدی: ۲۹۴)\nحضرت ہود علیہ السلام قوم سے یہ بات کیسے کہہ رہے تھے کہ ان پر عذاب واقع ہوچکا۔جبکہ اس وقت تک عذاب واقع نہیں ہوا تھا؟\nقَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ ٧٣\n(بَيِّنَةٞ مِّن رَّبِّكُمۡۖ) تمہارے رب کی طرف سے ایک واضح دلیل اور معجزہ۔ اور اس نشانی اور معجزے سے مراد اونٹنی ہے ۔ اس اونٹنی کی اونچی شان اور شرف بیان کرنے کے لئے اسے اللہ کی طرف نسبت دی گئی ۔(یعنی نَاقَةُ اللّٰهِ“اللہ کی اونٹنی” کہا گیا۔) یا یہ نسبت اس لئے کی گئی کہ اللہ نے اسے بغیر نرومادہ کے ملاپ کے پیدا کیا۔ دراصل قوم کے لوگوں نے خود حضرت صالح علیہ السلام سے یہ خواہش اور یہ مطالبہ کیا تھا کہ وہ ان کے لئے پتھر کی چٹان سے اس اونٹنی کو نکالیں، اور یہ عہد وپیمان کیا تھا کہ اگر وہ ایسا کر دکھائیں گے تو وہ لوگ ان کی نبوت کو تسلیم کرکے ان پر ایمان لے آئیں گے ۔ تب پتھر کی چٹان پھٹ پڑی اور ان کی نگاہوں کے سامنے اس سے اونٹنی نکل آئی۔پھر اس اونٹنی نے ایک بچے کو جنم دیا۔اس واضح دلیل اور معجزے کو دیکھ کر قوم کے کچھ لوگ حضرت صالح علیہ السلام پر ایمان لے آئے، جبکہ دوسرے لوگوں نے کفر اور انکار کیا۔ (ابن جُزی: ۱؍ ۳۶۰)\nاللہ نے جس کے حصے میں ہدایت نہیں لکھی ہے ،وہ بحث وتکرارکے ذریعہ سامنے والے کو صرف عاجز اور بے بس کرنا چاہتا ہے اور کچھ نہیں ۔ اس بات کو اس آیت کی مدد سے واضح کیجئے.\nwords\nبَسطَةًقوة /ضخامت.\nآلاَءَ اللهِاللہ کی نعمتیں.\nرِجسٌعذاب.\nوَقَطَعنَا دَابِرَہم نے ان سب کو ہلاک کردیا."],[160,"§الأعراف\ndeeds\nیہ دعا مانگئے: “اَللّٰہُمَّ حَبِّبْ اِلَىَّ الْاِیْمَانَ وَزَیِّنْہُ فِیْ قَلبِیْ، وَکَرِّہْ اِلَیَّ الکُفْرَ وَالْفُسُوْقَ وَالعِصْيَانَ، وَاجْعَلْنِیْ مِنَ الرَّاشِدِیْنَ”۔ اے اللہ ! ایمان کو میرے لئے محبوب بنا،اور اسے میرے دل میں مزین کردے ،کفر،فسق اور نافرمانی کو میرے لئے ناپسندیدہ بنادے، اور مجھے ہدایت یافتہ افراد میں شامل فرما.\nتکبر کے نقصان پر مشتمل ایک پیغام بھیجئے اور بتائیے کہ وہ شرک اور کفر کے اسباب میں سے ہے.\nکسی شخص نے آپ کو نصیحت کی ہو یا آپ کی خیر خواہی کی ہو تو اسے یاد کیجئے ،اس کا شکر ادا کیجئے، اور اس کے لئے دعا کیجئے.\nguid\nگناہوں سے نعمتیں ختم ہوجاتی ہیں، چنانچہ گناہوں سے دور رہئے.\nاپنے سے کم مرتبہ والوں سے بھی علم سیکھئے، اور کوئی کم درجہ والابھی حق بات کہے تو اسے قبول کیجئے.\nہلاکت وتباہی کے قریب ہونے کی نشانیوں میں سے ہے کہ لوگ نصیحت اور نصیحت کرنے والوں کو ناپسند کریں گے، اور خاص طور پر جبکہ وہ نصیحت ان کی خواہشات نفس کے خلاف ہو.\nrefl\nوَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ٧٤\nیعنی : فتنہ وفساد اور گناہوں کا ارتکاب کرکے زمین کوویران نہ بناؤ ،اس لئے کہ اللہ تعالیٰ کی نافرمانیاں آباد شہروں کو ویران کردیتی ہیں۔ اور واقعہ بھی یہی ہوا کہ قومِ صالح علیہ السلام کی بستیاں ان سے خالی ہوگئیں، اور ان کے مکانات اس طرح ویران رہ گئے کہ ان پر سناٹا اور ہُو کا عالم چھاگیا،اور وہ سنسان کھنڈربن گئے۔(السعدی: ۲۹۵)\nنافرمانیاں نعمتوں پر کیا اثر ڈالتی ہیں؟\nقَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لِلَّذِينَ ٱسۡتُضۡعِفُواْ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَٰلِحٗا مُّرۡسَلٞ مِّن رَّبِّهِۦۚ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ ٧٥\nقوم کے گھمنڈی سرداروں نے حضرت صالح علیہ السلام سے بحث وتکرار کا رخ موڑدیا،اور جو لوگ ان پر ایمان لائے تھے ان کے ایمان کی مضبوطی کا امتحان لینے لگے۔نیز ان مومنوں کے دلوں میں شک وشبہ ڈالنے کی کوششیں کرنے لگیں۔ اور مومنوں سے ان کے خطاب اور بات چیت کا مقصد تھا کہ حضرت صالح علیہ السلام کے دعوتی کام کو خراب کردیا جائے ،اسے بے اثر بنادیا جائے ۔ ان کا یہ خطاب ایسا ہی تھاجیسے خود حضرت صالح علیہ السلام کے ساتھ بات چیت کررہے ہوں۔ اور یہاں آیت میں ان سرداروں کو جو (ٱلَّذِينَ ٱسۡتَكۡبَرُواْ) (جنہوں نے تکبر کیا) کی صفت کے ساتھ ذکر کیا گیا ہے تو اس کا مقصد ان کی اس برائی کو بتانا ہے کہ وہ اکڑ اور گھمنڈ میں مبتلا تھے ۔قوم کے عام لوگوں کے سامنے اپنی بڑائی جتاتے اور شیخی بگھارتے تھے، نیز انہیں حقیر وذلیل سمجھتے تھے ۔ ساتھ ہی (ٱلَّذِينَ ٱسۡتَكۡبَرُواْ) کے الفاظ یہ بات بھی بتاتے ہیں کہ جو لوگ حضرت صالح علیہ السلام کی دعوت وتعلیم پر ایمان لائے تھے ،وہ قوم کے کمزورلوگ تھے ۔ (ابن عاشور: ۸؍۲۲۲)\nآیت بالا کو سامنے رکھ کر بتائیے کہ حضرت صالح علیہ السلام کی قوم نے لوگوں کو ان کی دعوت سے روکنے کے لئے کس انداز و اسالیب اپنائے ؟\nقَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا بِٱلَّذِيٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ ٧٦\nگھمنڈ اور تکبر نے انہیں اس بات پراکسایاکہ وہ اس حق کو نہ مانیں جسے قومِ صالح کے کمزور وناتواں لوگوں نے مان لیا تھا ۔ (السعدی: ۲۹۵)\nآیت کو نگاہ میں رکھ کرتکبر کے نقصانات میں سے ایک نقصان بتائیے؟\nفَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ ٧٧\n(فَعَقَرُواْ ٱلنَّاقَةَ) چنانچہ انہوں نے اونٹنی کی ٹانگیں کاٹ ڈالیں۔یعنی اسے ہلاک کردیا۔کاٹنے کے عمل کو قوم کے تمام لوگوں کی طرف منسوب کیا گیا ہے کہ سب نے کاٹا، اس لئے کہ وہ سب کے سب اس پر راضی تھے ۔ اگرچہ اس کام کو کرنے والا ان میں سے ایک ہی فرد تھا ۔ (ابن جُزی: ۱؍ ۳۶۰)\nاونٹنی کی ٹانگوں کو کاٹنے کا عمل پورے قبیلے کی طرف کیوں منسوب کیا گیا ہے، جبکہ کاٹنے والا ایک ہی شخص تھا ؟\nفَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ ٧٩\nحضرت صالح علیہ السلام کا یہ کہنا (لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ) تم نصیحت وخیر خواہی کرنے والوں کو پسند نہیں کرتے۔ اس قول سے یہ مطلب نکلتا ہے کہ قوم صالح کے افراد نے اپنی سوجھ بوجھ پر اپنی شہوتوں او ر خواہشوں کو غالب کررکھا تھا کیونکہ جس نفس کو نصیحت کی جارہی ہو اسے نصیحت کرنے والے کی بات بڑی گراں معلوم ہوتی ہے ۔ اس لئے کہ وہ اس کے نفس کی خواہش وشہوت کے خلاف ہوتی ہے ۔ (ابن عطیہ: ۲؍ ۴۲۴)\nاکثر لوگ ان لوگوں کو پسند کیوں نہیں کرتے جو ان کی بھلائی چاہتے اور انہیں نصیحت کرتے ہیں؟\nوَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ ٨٠\n(أَتَأۡتُونَ ٱلۡفَٰحِشَةَ) کیا تم بے حیائی کا کام کرتے ہو! یعنی: ایسی بری خصلت کا ارتکاب کرتے ہو جواس قدر بری ہے کہ اس کی سنگینی ،برائی، فحاشی،بدکاری اور بدکرداری کی تمام قسموں کو اپنے اندر سمیٹے ہوئے ہے ۔ (مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ) جو (برا کام)تم سے پہلے اہلِ عالَم میں سے کسی نے بھی نہیں کیا ۔ اب اس حرکت کا “فاحشہ” یعنی قباحت وبرائی والا ہونا پہلے ہی ایک قبیح ترین چیز تھی ۔پھر یہ بات کہ حضرت لوط علیہ السلام کی قوم نے اس بدچلنی کو ایجادبھی کیا تھا ،اور اپنے بعد آنے والوں کے لئے اسے نمونہ بنادیا۔ یہ ایسی بات ہے جو اُن کے جرم کو برے سے برا بناتی ہے ۔ (السعدی: ۲۹۶)\nنافرمانی کا گناہ کب دوچندہوتا ہے ؟ آیت کے دائرے میں بیان کیجئے.\nإِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ ٨١\nیعنی:تم ایسے لوگ ہوجن میں شہوت وخواہش میں حد سے آگے نکل جانے کی عادت گھر کرچکی ہے۔غرض یہی وجہ تھی کہ جب وہ لوگ معمول کی جنسی لذت سے اکتا گئے ، تو نامانوس اورغیرفطری خواہش (یعنی اغلام بازی) یعنی مَردوں کے ساتھ غیر فطری جنسی عمل کے پیچھے پڑ گئے ۔ (ابن عاشور: ۸؍۲۳۲)\nقوم لوط کو(قَوۡمٞ مُّسۡرِفُونَ) یعنی حد سے آگے بڑھنے والے لوگ کیوں کہا گیا؟\nwords\nوَبَوَّأَكُمتمہیں بسایا/ ٹھکانا دیا.\nوَلاَ تَعثَوانہ کوشش کرو.\nفَعَقَرُوااس کو قتل کردیا(کونچیں کاٹ ڈالیں).\nوَعَتَوااور انہوں نے تکبر کیا.\nالرَّجفَةُبہت سخت زلزلہ."]])